skip_unless_full_tests()

# Expected values are SymPy's outputs for the same calls (sympy/matrices/tests and
# sympy/geometry/tests); the rows come from the battery that compares this port with SymPy.

.mgs_show <- function(v) {
  if (is.null(v)) return("None")
  if (inherits(v, "GeoEntity")) return(format(v))
  if (is.logical(v) && length(v) == 1L) return(if (is.na(v)) "None" else if (v) "True" else "False")
  if (is.character(v) && length(v) == 1L) return(v)
  if (is.numeric(v) && length(v) == 1L && is.null(dim(v))) return(as.character(v))
  if (is.list(v) && !is_sym(v) && !inherits(v, c("symmatrix", "GeoEntity")) && is.null(attr(v, "class"))) {
    if (!is.null(names(v)) && all(nzchar(names(v))) && isTRUE(attr(v, "dict")))
      return(paste0("{", paste(names(v), vapply(v, .mgs_show, ""), sep = ": ", collapse = ", "), "}"))
    return(paste0("[", paste(vapply(v, .mgs_show, ""), collapse = ", "), "]"))
  }
  gsub("\n", "\\n", paste(sstr(v), collapse = "\n"), fixed = TRUE)
}
.mgs <- function(expr) tryCatch({ utils::capture.output(v <- expr); .mgs_show(v) }, error = function(e) {
  cl <- setdiff(class(e), c("simpleError", "error", "condition"))
  gsub("\n", "\\n", paste0("ERR ", if (length(cl)) cl[1] else "Error", ": ", conditionMessage(e)), fixed = TRUE)
})
.bat_zip <- function(...) unname(Map(list, ...))
.bat_in <- function(x, l) any(vapply(l, function(z) identical(.mgs_show(z), .mgs_show(x)), TRUE))
.zb <- function(v) as.list(as.integer(unlist(v)) - 1L)
.zb_rref <- function(r) { if (is.list(r) && !inherits(r, "symmatrix")) r[[2L]] <- .zb(r[[2L]]); r }
.zb_cc <- function(r) lapply(r, .zb)
.zb_last <- function(r) { k <- length(r); r[[k]] <- if (length(r[[k]]) && is.list(r[[k]])) lapply(r[[k]], .zb) else .zb(r[[k]]); names(r) <- NULL; r }
.mgs_env <- function() {
  e <- new.env(parent = parent.frame())
  for (nm in c("a", "b", "c", "d", "k", "n", "t", "x", "y", "z", "w")) assign(nm, Symbol(nm), envir = e)
  e
}

# matgeo module
.mge <- .mgs_env()

test_that("matgeo module matches SymPy", {
  expect_identical(.mgs(evalq({ Matrix(list(list(1, 1), list(0, 1))) %^% n }, .mge)), "Matrix([[1, n], [0, 1]])")
  expect_identical(.mgs(evalq({ Matrix(list(list(2, 1), list(0, 2))) %^% n }, .mge)), "Matrix([[2^n, 2^(n - 1)*n], [0, 2^n]])")
  expect_identical(.mgs(evalq({ Matrix(list(list(1, 1), list(1, 0))) %^% n }, .mge)), "Matrix([[(1/2 - sqrt(5)/2)^n*(1/2 - sqrt(5)/10) + (1/2 + sqrt(5)/2)^n*(sqrt(5)/10 + 1/2), -sqrt(5)*(1/2 - sqrt(5)/2)^n/5 + sqrt(5)*(1/2 + sqrt(5)/2)^n/5], [(1/2 - sqrt(5)/2)^n*(1/2 - sqrt(5)/10)*(-sqrt(5)/2 - 1/2) + (-1/2 + sqrt(5)/2)*(1/2 + sqrt(5)/2)^n*(sqrt(5)/10 + 1/2), -sqrt(5)*(1/2 - sqrt(5)/2)^n*(-sqrt(5)/2 - 1/2)/5 + sqrt(5)*(-1/2 + sqrt(5)/2)*(1/2 + sqrt(5)/2)^n/5]])")
  expect_identical(.mgs(evalq({ Matrix(list(list(1, 2), list(3, 4))) %^% Rational(1, 2) }, .mge)), "Matrix([[2*(1/4 - sqrt(33)/44)*sqrt(5/2 + sqrt(33)/2) + 2*sqrt(5/2 - sqrt(33)/2)*(sqrt(33)/44 + 1/4), 2*sqrt(33)*sqrt(5/2 + sqrt(33)/2)/33 - 2*sqrt(33)*sqrt(5/2 - sqrt(33)/2)/33], [(1/4 - sqrt(33)/44)*(3/2 + sqrt(33)/2)*sqrt(5/2 + sqrt(33)/2) + (3/2 - sqrt(33)/2)*sqrt(5/2 - sqrt(33)/2)*(sqrt(33)/44 + 1/4), sqrt(33)*(3/2 + sqrt(33)/2)*sqrt(5/2 + sqrt(33)/2)/33 - sqrt(33)*(3/2 - sqrt(33)/2)*sqrt(5/2 - sqrt(33)/2)/33]])")
  expect_identical(.mgs(evalq({ GramSchmidt(list(Matrix(list(1, 2, 3)), Matrix(list(2, 4, 6)))) }, .mge)), "ERR ValueError: GramSchmidt: vector set not linearly independent")
  expect_identical(.mgs(evalq({ arbitrary_point(Circle(Point(0, 0), 2)) }, .mge)), "Point2D(2*cos(t), 2*sin(t))")
  expect_identical(.mgs(evalq({ arbitrary_point(Ellipse(Point(0, 0), 3, 2)) }, .mge)), "Point2D(3*cos(t), 2*sin(t))")
  expect_identical(.mgs(evalq({ Polygon(Point(0, 0), Point(1, 0), Point(2, 0), Point(1, 1)) }, .mge)), "Triangle(Point2D(0, 0), Point2D(2, 0), Point2D(1, 1))")
  expect_identical(.mgs(evalq({ Triangle(Point(0, 0), Point(1, 1), Point(2, 2)) }, .mge)), "Segment2D(Point2D(0, 0), Point2D(2, 2))")
  expect_identical(.mgs(evalq({ Point(0.5, 0.25) }, .mge)), "Point2D(1/2, 1/4)")
  expect_identical(.mgs(evalq({ equation(Circle(Point(1, 2), 3)) }, .mge)), "(x - 1)^2 + (y - 2)^2 - 9")
  expect_identical(.mgs(evalq({ intersection(Plane(Point3D(0, 0, 0), normal_vector = c(1, 0, 0)), Plane(Point3D(0, 0, 0), normal_vector = c(0, 1, 0))) }, .mge)), "[Line3D(Point3D(0, 0, 0), Point3D(0, 0, 1))]")
  expect_identical(.mgs(evalq({ Line(Point(0, 0), Point(1, 1)) == Line(Point(0, 0), Point(2, 2)) }, .mge)), "False")
  expect_identical(.mgs(evalq({ Point(1, 2) + Point(3, 4) }, .mge)), "Point2D(4, 6)")
  expect_identical(.mgs(evalq({ Point(1, 2) * 3 }, .mge)), "Point2D(3, 6)")
  expect_identical(.mgs(evalq({ Segment(Point(1, 1), Point(1, 1)) }, .mge)), "Point2D(1, 1)")
  expect_identical(.mgs(evalq({ Circle(Point(0, 0), Point(1, 0), Point(0, 1)) }, .mge)), "Circle(Point2D(1/2, 1/2), sqrt(2)/2)")
})

