test_that("matrixbase: test__MinimalMatrix matches SymPy", {
  try(utils::capture.output(evalq({ x <- Matrix(2, 3, list(1, 2, 3, 4, 5, 6)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ x$nrow }, .mge)), "2")
  expect_identical(.mgs(evalq({ x$ncol }, .mge)), "3")
  expect_identical(.mgs(evalq({ x$data[[3]] }, .mge)), "3")
  expect_identical(.mgs(evalq({ x[2, 2] }, .mge)), "5")
  expect_identical(.mgs(evalq({ x[, , drop = FALSE] }, .mge)), "Matrix([[1, 2, 3], [4, 5, 6]])")
  expect_identical(.mgs(evalq({ Matrix(x) }, .mge)), "Matrix([[1, 2, 3], [4, 5, 6]])")
  expect_identical(.mgs(evalq({ Matrix(list(list(1, 2, 3), list(4, 5, 6))) }, .mge)), "Matrix([[1, 2, 3], [4, 5, 6]])")
  expect_identical(.mgs(evalq({ Matrix(list(list(1, 2, 3), list(4, 5, 6))) }, .mge)), "Matrix([[1, 2, 3], [4, 5, 6]])")
  expect_identical(.mgs(evalq({ Matrix(list(list(1, 2, 3), list(4, 5, 6))) }, .mge)), "Matrix([[1, 2, 3], [4, 5, 6]])")
  expect_identical(.mgs(evalq({ Matrix(list(list(1, 2, 3), list(4, 5, 6))) }, .mge)), "Matrix([[1, 2, 3], [4, 5, 6]])")
  expect_identical(.mgs(evalq({ !(Matrix(list(list(1, 2), list(3, 4), list(5, 6))) == x) }, .mge)), "True")
})

