test_that("matrixbase: test_power matches SymPy", {
  expect_identical(.mgs(evalq({ Matrix(list(1, 2)) %^% 2 }, .mge)), "ERR NonSquareMatrixError: ")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(2, 3), list(4, 5))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(2, 1, 3), list(4, 2, 4), list(6, 12, 1))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(1, 2), list(4, 5))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(33, 24), list(48, 57))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(0, 4), list(-1, 5))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ Matrix(list(list(a %^% n, (a %^% (n - 1)) * n, (((a %^% n) * (n^2)) - ((a %^% n) * n)) / (2 * (a %^% 2))), list(0, a %^% n, (a %^% (n - 1)) * n), list(0, 0, a %^% n))) }, .mge)), "ERR NonSquareMatrixError: ")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(1, 0), list(1, 7))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(2))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(0, 1, 0), list(0, 0, 1), list(0, 0, 0))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ A %^% 2.1 }, .mge)), "ERR NonInvertibleMatrixError: Non-invertible matrix can only be raised to a nonnegative integer")
  expect_identical(.mgs(evalq({ A %^% Rational(3, 2) }, .mge)), "ERR NonInvertibleMatrixError: Non-invertible matrix can only be raised to a nonnegative integer")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(8, 1), list(3, 2))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(0, 0, 1), list(0, 0, 1), list(0, 0, 1))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(0, 1, 0), list(0, 0, 1), list(0, 0, 1))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ n <- Symbol("n", integer = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ n <- Symbol("n", integer = TRUE, negative = TRUE) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ A %^% n }, .mge)), "ERR NonInvertibleMatrixError: Non-invertible matrix can only be raised to a nonnegative integer")
  try(utils::capture.output(evalq({ n <- Symbol("n", integer = TRUE, nonnegative = TRUE) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ A %^% Rational(3, 2) }, .mge)), "ERR NonInvertibleMatrixError: Non-invertible matrix can only be raised to a nonnegative integer")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(0, 0, 1), list(3, 0, 1), list(4, 3, 1))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(0, 1, 0), list(-1, 0, 0), list(0, 0, 0))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ n <- Symbol("n") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ An <- A %^% n }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(0, 0, 0), list(0, 0, 0), list(0, 0, 0))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ n <- Symbol("n", integer = TRUE, positive = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ n <- Symbol("n", integer = TRUE, nonnegative = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(2, 0, 0), list(0, 2, 0), list(0, 0, 2))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(0, 1, 0), list(0, 0, 1), list(0, 0, 1))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ A %^% 2.1 }, .mge)), "ERR NonInvertibleMatrixError: Non-invertible matrix can only be raised to a nonnegative integer")
  expect_identical(.mgs(evalq({ A %^% sym_I }, .mge)), "ERR NonInvertibleMatrixError: Non-invertible matrix can only be raised to a nonnegative integer")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(S_Half, S_Half), list(S_Half, S_Half))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(1, 1), list(3, 3))) }, .mge)), silent = TRUE)
})

test_that("matrixbase: test_vech matches SymPy", {
  try(utils::capture.output(evalq({ m <- Matrix(list(list(1, 2), list(2, 3))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m_vech <- vech(m) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m_vech <- vech(m, diagonal = FALSE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(list(list(1, x * (x + y)), list((y * x) + (x^2), 1))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m_vech <- vech(m, diagonal = FALSE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(list(list(1, x * (x + y)), list(y * x, 1))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m_vech <- vech(m, diagonal = FALSE, check_symmetry = FALSE) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ vech(Matrix(list(list(1, 3)))) }, .mge)), "ERR NonSquareMatrixError: ")
  expect_identical(.mgs(evalq({ vech(Matrix(list(list(1, 3), list(2, 4)))) }, .mge)), "ERR ValueError: The matrix is not symmetric.")
  expect_identical(.mgs(evalq({ vech(Matrix(list(list(1, 3)))) }, .mge)), "ERR NonSquareMatrixError: ")
  expect_identical(.mgs(evalq({ vech(Matrix(list(list(1, 3), list(2, 4)))) }, .mge)), "ERR ValueError: The matrix is not symmetric.")
})

test_that("matrixbase: test_diagonalization matches SymPy", {
  try(utils::capture.output(evalq({ m <- Matrix(list(list(1, 2 + sym_I), list(2 - sym_I, 3))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(3, 2, list(-3, 1, -3, 20, 3, 10)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ diagonalize(m) }, .mge)), "ERR NonSquareMatrixError: ")
  try(utils::capture.output(evalq({ m <- diag_matrix(1, 2, 3) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- diagonalize(m); P <- .tup[[1]]; D <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(2, 2, list(0, 1, 1, 0)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- diagonalize(m); P <- .tup[[1]]; D <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(2, 2, list(1, 0, 0, 3)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- diagonalize(m); P <- .tup[[1]]; D <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(2, 2, list(1, 1, 0, 0)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- diagonalize(m); P <- .tup[[1]]; D <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(3, 3, list(1, 2, 0, 0, 3, 0, 2, -4, 2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- diagonalize(m); P <- .tup[[1]]; D <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(2, 2, list(1, 0, 0, 0)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- diagonalize(m); P <- .tup[[1]]; D <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(2, 2, list(0, 1, -1, 0)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ diagonalize(m, TRUE) }, .mge)), "ERR MatrixError: Matrix is not diagonalizable")
  try(utils::capture.output(evalq({ .tup <- diagonalize(m); P <- .tup[[1]]; D <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(2, 2, list(0, 1, 0, 0)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ diagonalize(m) }, .mge)), "ERR MatrixError: Matrix is not diagonalizable")
  try(utils::capture.output(evalq({ m <- Matrix(3, 3, list(-3, 1, -3, 20, 3, 10, 2, -2, 4)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ diagonalize(m) }, .mge)), "ERR MatrixError: Matrix is not diagonalizable")
  try(utils::capture.output(evalq({ a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(2, 2, list(a, c, c, b)) }, .mge)), silent = TRUE)
})

