  try(utils::capture.output(evalq({ Jmust <- Matrix(3, 3, list(2, 1, 0, 0, 2, 0, 0, 0, 2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- jordan_form(m); P <- .tup[[1]]; J <- .tup[[2]] }, .mge)), silent = TRUE)
