  try(utils::capture.output(evalq({ Jmust <- Matrix(3, 3, list(-1, 1, 0, 0, -1, 0, 0, 0, -1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- jordan_form(m); P <- .tup[[1]]; J <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(3, 3, list(4, -5, 2, 5, -7, 3, 6, -9, 4)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ Jmust <- Matrix(3, 3, list(1, 0, 0, 0, 0, 1, 0, 0, 0)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- jordan_form(m); P <- .tup[[1]]; J <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(4, 4, list(6, 5, -2, -3, -3, -1, 3, 3, 2, 1, -2, -3, -1, 1, 5, 5)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ Jmust <- Matrix(4, 4, list(2, 1, 0, 0, 0, 2, 0, 0, 0, 0, 2, 1, 0, 0, 0, 2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- jordan_form(m); P <- .tup[[1]]; J <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(4, 4, list(6, 2, -8, -6, -3, 2, 9, 6, 2, -2, -8, -6, -1, 0, 3, 4)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ Jmust <- Matrix(4, 4, list(-2, 0, 0, 0, 0, 2, 1, 0, 0, 0, 2, 0, 0, 0, 0, 2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- jordan_form(m); P <- .tup[[1]]; J <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(4, 4, list(5, 4, 2, 1, 0, 1, -1, -1, -1, -1, 3, 0, 1, 1, -1, 2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ Jmust <- Matrix(4, 4, list(2, 0, 0, 0, 0, 1, 0, 0, 0, 0, 4, 1, 0, 0, 0, 4)) }, .mge)), silent = TRUE)
