test_that("matrixbase: test_errors matches SymPy", {
  expect_identical(.mgs(evalq({ inverse(Matrix(list(list(1, 2, 3), list(2, 3, 0)))) }, .mge)), "ERR NonSquareMatrixError: A Matrix must be square to invert.")
  expect_identical(.mgs(evalq({ row_join(Matrix(1, 2, list(1, 2)), Matrix(list(list(1, 2), list(3, 4)))) }, .mge)), "ERR ShapeError: The matrices have incompatible number of rows (1 and 2)")
  expect_identical(.mgs(evalq({ col_join(Matrix(list(1, 2)), Matrix(list(list(1, 2), list(3, 4)))) }, .mge)), "ERR ShapeError: The matrices have incompatible number of columns (1 and 2)")
  expect_identical(.mgs(evalq({ row_insert(Matrix(list(1)), 2, Matrix(list(list(1, 2), list(3, 4)))) }, .mge)), "ERR ShapeError: The matrices have incompatible number of columns (1 and 2)")
  expect_identical(.mgs(evalq({ col_insert(Matrix(list(1)), 2, Matrix(list(list(1, 2), list(3, 4)))) }, .mge)), "ERR ShapeError: The matrices have incompatible number of rows (1 and 2)")
  expect_identical(.mgs(evalq({ minor_submatrix(Matrix(list(list(1, 2), list(3, 4))), 5, 6) }, .mge)), "ERR ValueError: `i` and `j` must satisfy 0 <= i < ``M.rows`` (2)and 0 <= j < ``M.cols`` (2).")
  expect_identical(.mgs(evalq({ matrix_exp(Matrix(list(1, 2, 3))) }, .mge)), "ERR NonSquareMatrixError: Exponentiation is valid only for square matrices")
  expect_identical(.mgs(evalq({ inverse(Matrix(list(1, 2)), method = "not a method") }, .mge)), "ERR NonSquareMatrixError: A Matrix must be square to invert.")
  expect_identical(.mgs(evalq({ inverse_GE(Matrix(list(1, 2))) }, .mge)), "ERR NonSquareMatrixError: A Matrix must be square to invert.")
  expect_identical(.mgs(evalq({ inverse_LU(Matrix(list(1, 2))) }, .mge)), "ERR NonSquareMatrixError: A Matrix must be square to invert.")
  expect_identical(.mgs(evalq({ det(Matrix(list(list(1, 2), list(3, 4))), method = "Not a real method") }, .mge)), "ERR ValueError: Determinant method 'not a real method' unrecognized")
  expect_identical(.mgs(evalq({ det(Matrix(list(list(1, 2, 3, 4), list(5, 6, 7, 8), list(9, 10, 11, 12), list(13, 14, 15, 16))), iszerofunc = "Not function") }, .mge)), "ERR ValueError: Zero testing method 'Not function' unrecognized")
  try(utils::capture.output(evalq({ M <- Matrix(list(list(1, 2, 3, 4), list(5, 6, 7, 8), list(9, 10, 11, 12), list(13, 14, 15, 16))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ det(M, "method=LU_decomposition()") }, .mge)), "ERR ValueError: Determinant method 'method=lu_decomposition()' unrecognized")
  try(utils::capture.output(evalq({ V <- Matrix(list(list(10, 10, 10))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ M <- Matrix(list(list(1, 2, 3), list(2, 3, 4), list(3, 4, 5))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ M <- Matrix(list(list(1, 2, 3), list(2, 3, 4), list(3, 4, 5))) }, .mge)), silent = TRUE)
})

test_that("matrixbase: test_cholesky matches SymPy", {
  expect_identical(.mgs(evalq({ cholesky(Matrix(list(1, 2))) }, .mge)), "ERR NonSquareMatrixError: Matrix must be square.")
  expect_identical(.mgs(evalq({ cholesky(Matrix(list(list(1, 2), list(3, 4)))) }, .mge)), "ERR ValueError: Matrix must be Hermitian.")
  expect_identical(.mgs(evalq({ cholesky(Matrix(list(list(5 + sym_I, 0), list(0, 1)))) }, .mge)), "ERR ValueError: Matrix must be Hermitian.")
  expect_identical(.mgs(evalq({ cholesky(Matrix(list(list(1, 5), list(5, 1)))) }, .mge)), "ERR NonPositiveDefiniteMatrixError: Matrix must be positive-definite")
  expect_identical(.mgs(evalq({ cholesky(Matrix(list(list(1, 2), list(3, 4))), hermitian = FALSE) }, .mge)), "ERR ValueError: Matrix must be symmetric.")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(1, 5), list(5, 1))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ L <- cholesky(A, hermitian = FALSE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(25, 15, -5), list(15, 18, 0), list(-5, 0, 11))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ L <- cholesky(A) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(4, (-2) * sym_I, 2 + (2 * sym_I)), list(2 * sym_I, 2, (-1) + sym_I), list(2 - (2 * sym_I), (-1) - sym_I, 11))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ cholesky(Matrix(list(1, 2))) }, .mge)), "ERR NonSquareMatrixError: Matrix must be square.")
  expect_identical(.mgs(evalq({ cholesky(Matrix(list(list(1, 2), list(3, 4)))) }, .mge)), "ERR ValueError: Matrix must be Hermitian.")
  expect_identical(.mgs(evalq({ cholesky(Matrix(list(list(5 + sym_I, 0), list(0, 1)))) }, .mge)), "ERR ValueError: Matrix must be Hermitian.")
  expect_identical(.mgs(evalq({ cholesky(Matrix(list(list(1, 5), list(5, 1)))) }, .mge)), "ERR NonPositiveDefiniteMatrixError: Matrix must be positive-definite")
  expect_identical(.mgs(evalq({ cholesky(Matrix(list(list(1, 2), list(3, 4))), hermitian = FALSE) }, .mge)), "ERR ValueError: Matrix must be symmetric.")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(1, 5), list(5, 1))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ L <- cholesky(A, hermitian = FALSE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(25, 15, -5), list(15, 18, 0), list(-5, 0, 11))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ L <- cholesky(A) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(4, (-2) * sym_I, 2 + (2 * sym_I)), list(2 * sym_I, 2, (-1) + sym_I), list(2 - (2 * sym_I), (-1) - sym_I, 11))) }, .mge)), silent = TRUE)
})

