test_that("decompositions: test_LDLdecomposition matches SymPy", {
  expect_identical(.mgs(evalq({ LDLdecomposition(Matrix(list(1, 2))) }, .mge)), "ERR NonSquareMatrixError: Matrix must be square.")
  expect_identical(.mgs(evalq({ LDLdecomposition(Matrix(list(list(1, 2), list(3, 4)))) }, .mge)), "ERR ValueError: Matrix must be Hermitian.")
  expect_identical(.mgs(evalq({ LDLdecomposition(Matrix(list(list(5 + sym_I, 0), list(0, 1)))) }, .mge)), "ERR ValueError: Matrix must be Hermitian.")
  expect_identical(.mgs(evalq({ LDLdecomposition(Matrix(list(list(1, 5), list(5, 1)))) }, .mge)), "ERR NonPositiveDefiniteMatrixError: Matrix must be positive-definite")
  expect_identical(.mgs(evalq({ LDLdecomposition(Matrix(list(list(1, 2), list(3, 4))), hermitian = FALSE) }, .mge)), "ERR ValueError: Matrix must be symmetric.")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(1, 5), list(5, 1))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- LDLdecomposition(A, hermitian = FALSE); L <- .tup[[1]]; D <- .tup[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ (L %*% D) %*% t(L) }, .mge)), "Matrix([[1, 5], [5, 1]])")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(25, 15, -5), list(15, 18, 0), list(-5, 0, 11))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- LDLdecomposition(A); L <- .tup[[1]]; D <- .tup[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ (L %*% D) %*% t(L) }, .mge)), "Matrix([[25, 15, -5], [15, 18, 0], [-5, 0, 11]])")
  expect_identical(.mgs(evalq({ is_lower(L) }, .mge)), "True")
  expect_identical(.mgs(evalq({ L }, .mge)), "Matrix([[1, 0, 0], [3/5, 1, 0], [-1/5, 1/3, 1]])")
  expect_identical(.mgs(evalq({ is_diagonal(D) }, .mge)), "True")
  expect_identical(.mgs(evalq({ D }, .mge)), "Matrix([[25, 0, 0], [0, 9, 0], [0, 0, 9]])")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(4, (-2) * sym_I, 2 + (2 * sym_I)), list(2 * sym_I, 2, (-1) + sym_I), list(2 - (2 * sym_I), (-1) - sym_I, 11))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- LDLdecomposition(A); L <- .tup[[1]]; D <- .tup[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ expand_mul((L %*% D) %*% adjoint(L)) }, .mge)), "Matrix([[4, -2*I, 2 + 2*I], [2*I, 2, -1 + I], [2 - 2*I, -1 - I, 11]])")
  expect_identical(.mgs(evalq({ expand(L) }, .mge)), "Matrix([[1, 0, 0], [I/2, 1, 0], [1/2 - I/2, 0, 1]])")
  expect_identical(.mgs(evalq({ expand(D) }, .mge)), "Matrix([[4, 0, 0], [0, 1, 0], [0, 0, 9]])")
  expect_identical(.mgs(evalq({ LDLdecomposition(Matrix(list(1, 2))) }, .mge)), "ERR NonSquareMatrixError: Matrix must be square.")
  expect_identical(.mgs(evalq({ LDLdecomposition(Matrix(list(list(1, 2), list(3, 4)))) }, .mge)), "ERR ValueError: Matrix must be Hermitian.")
  expect_identical(.mgs(evalq({ LDLdecomposition(Matrix(list(list(5 + sym_I, 0), list(0, 1)))) }, .mge)), "ERR ValueError: Matrix must be Hermitian.")
  expect_identical(.mgs(evalq({ LDLdecomposition(Matrix(list(list(1, 5), list(5, 1)))) }, .mge)), "ERR NonPositiveDefiniteMatrixError: Matrix must be positive-definite")
  expect_identical(.mgs(evalq({ LDLdecomposition(Matrix(list(list(1, 2), list(3, 4))), hermitian = FALSE) }, .mge)), "ERR ValueError: Matrix must be symmetric.")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(1, 5), list(5, 1))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- LDLdecomposition(A, hermitian = FALSE); L <- .tup[[1]]; D <- .tup[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ (L %*% D) %*% t(L) }, .mge)), "Matrix([[1, 5], [5, 1]])")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(25, 15, -5), list(15, 18, 0), list(-5, 0, 11))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- LDLdecomposition(A); L <- .tup[[1]]; D <- .tup[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ (L %*% D) %*% t(L) }, .mge)), "Matrix([[25, 15, -5], [15, 18, 0], [-5, 0, 11]])")
  expect_identical(.mgs(evalq({ is_lower(L) }, .mge)), "True")
  expect_identical(.mgs(evalq({ L }, .mge)), "Matrix([[1, 0, 0], [3/5, 1, 0], [-1/5, 1/3, 1]])")
  expect_identical(.mgs(evalq({ is_diagonal(D) }, .mge)), "True")
  expect_identical(.mgs(evalq({ D }, .mge)), "Matrix([[25, 0, 0], [0, 9, 0], [0, 0, 9]])")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(4, (-2) * sym_I, 2 + (2 * sym_I)), list(2 * sym_I, 2, (-1) + sym_I), list(2 - (2 * sym_I), (-1) - sym_I, 11))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- LDLdecomposition(A); L <- .tup[[1]]; D <- .tup[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ expand_mul((L %*% D) %*% adjoint(L)) }, .mge)), "Matrix([[4, -2*I, 2 + 2*I], [2*I, 2, -1 + I], [2 - 2*I, -1 - I, 11]])")
})

