test_that("solvers: test_LUsolve matches SymPy", {
  try(utils::capture.output(evalq({ A <- Matrix(list(list(2, 3, 5), list(3, 6, 2), list(8, 3, 6))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ x <- Matrix(3, 1, list(3, 7, 5)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ b <- A %*% x }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ soln <- LUsolve(A, b) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ soln }, .mge)), "Matrix([[3], [7], [5]])")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(0, -1, 2), list(5, 10, 7), list(8, 3, 4))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ x <- Matrix(3, 1, list(-1, 2, 5)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ b <- A %*% x }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ soln <- LUsolve(A, b) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ soln }, .mge)), "Matrix([[-1], [2], [5]])")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(2, 1), list(1, 0), list(1, 0))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ b <- Matrix(list(3, 1, 1)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ LUsolve(A, b) }, .mge)), "Matrix([[1], [1]])")
  try(utils::capture.output(evalq({ b <- Matrix(list(3, 1, 2)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ LUsolve(A, b) }, .mge)), "ERR ValueError: The system is inconsistent.")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(0, -1, 2), list(5, 10, 7), list(8, 3, 4), list(2, 3, 5), list(3, 6, 2), list(8, 3, 6))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ x <- Matrix(list(2, 1, -4)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ b <- A %*% x }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ soln <- LUsolve(A, b) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ soln }, .mge)), "Matrix([[2], [1], [-4]])")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(0, -1, 2), list(5, 10, 7))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ x <- Matrix(list(-1, 2, 0)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ b <- A %*% x }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ LUsolve(A, b) }, .mge)), "ERR NotImplementedError: Underdetermined systems not supported.")
  try(utils::capture.output(evalq({ .untranslated <- TRUE }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ b <- zeros(4, 1) }, .mge)), silent = TRUE)
})

