  try(utils::capture.output(evalq({ b <- A %*% x }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ soln <- cholesky_solve(A, b) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ soln }, .mge)), "Matrix([[4], [-3]])")
