  try(utils::capture.output(evalq({ x <- Matrix(list(-2, 1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ b <- A %*% x }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ soln <- cholesky_solve(A, b) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ expand_mul(soln) }, .mge)), "Matrix([[-2], [1]])")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(9 * sym_I, 3), list((-3) + sym_I, 5))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ x <- Matrix(list(2 + (3 * sym_I), -1)) }, .mge)), silent = TRUE)
