  try(utils::capture.output(evalq({ soln <- cholesky_solve(A, b) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ expand_mul(soln) }, .mge)), "Matrix([[2 + 3*I], [-1]])")
  try(utils::capture.output(evalq({ a00 <- Symbol("a00"); a01 <- Symbol("a01"); a11 <- Symbol("a11"); b0 <- Symbol("b0"); b1 <- Symbol("b1") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(a00, a01), list(a01, a11))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ b <- Matrix(list(b0, b1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ x <- cholesky_solve(A, b) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ simplify(A %*% x) }, .mge)), "Matrix([[b0], [b1]])")
})

