test_that("solvers: test_pinv_solve matches SymPy", {
  try(utils::capture.output(evalq({ A <- Matrix(list(list(1, 5), list(7, 9))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ B <- Matrix(list(12, 13)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ pinv_solve(A, B) }, .mge)), "Matrix([[-43/26], [71/26]])")
  expect_identical(.mgs(evalq({ pinv_solve(A, B) }, .mge)), "Matrix([[-43/26], [71/26]])")
  expect_identical(.mgs(evalq({ pinv_solve(A, B) }, .mge)), "Matrix([[-43/26], [71/26]])")
  expect_identical(.mgs(evalq({ (A %*% pinv(A)) %*% B }, .mge)), "Matrix([[12], [13]])")
  try(utils::capture.output(evalq({ B <- Matrix(list(list(12, 13, 14), list(15, 16, 17))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ pinv_solve(A, B) }, .mge)), "Matrix([[-33/26, -37/26, -41/26], [69/26, 75/26, 81/26]])")
  expect_identical(.mgs(evalq({ pinv_solve(A, B) }, .mge)), "Matrix([[-33/26, -37/26, -41/26], [69/26, 75/26, 81/26]])")
  expect_identical(.mgs(evalq({ pinv_solve(A, B) }, .mge)), "Matrix([[-33/26, -37/26, -41/26], [69/26, 75/26, 81/26]])")
  expect_identical(.mgs(evalq({ (A %*% pinv(A)) %*% B }, .mge)), "Matrix([[12, 13, 14], [15, 16, 17]])")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(1, 0, 1), list(0, 1, 1))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ B <- Matrix(list(5, 7)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ solution <- pinv_solve(A, B) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .untranslated <- TRUE }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ (A %*% pinv(A)) %*% B }, .mge)), "Matrix([[5], [7]])")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(1, 0), list(0, 0), list(0, 1))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ B <- Matrix(list(3, 2, 1)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ pinv_solve(A, B) }, .mge)), "Matrix([[3], [1]])")
  expect_identical(.mgs(evalq({ ((A %*% pinv(A)) %*% B) != B }, .mge)), "True")
})

