  try(utils::capture.output(evalq({ A <- Matrix(list(list(1, 2, 3, 4), list(5, 6, 7, 8), list(2, 4, 6, 8))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ b <- Matrix(list(0, 1, 0)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- gauss_jordan_solve(A, b); sol <- .tup[[1]]; params <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .untranslated <- TRUE }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ M <- Matrix(list(list(0, 1, 0, 0, 0, 0), list(0, 0, 0, 1, 0, ._x0))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .untranslated <- TRUE }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ b <- M[, 0:NROWCOL, drop = FALSE] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .untranslated <- TRUE }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(1, 2, 3, 4), list(5, 6, 7, 8), list(2, 4, 6, 8))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ b <- Matrix(list(1, 1, 1)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ gauss_jordan_solve(A, b) }, .mge)), "ERR ValueError: Linear system has no solution")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(1, 0), list(0, 1))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ B <- Matrix(list(1, 2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- gauss_jordan_solve(A, B); sol <- .tup[[1]]; params <- .tup[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ sol }, .mge)), "Matrix([[1], [2]])")
  expect_identical(.mgs(evalq({ params }, .mge)), "Matrix(0, 1, [])")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(1, 0, 0, 0), list(0, 0, 0, 1))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ b <- Matrix(list(1, 1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- gauss_jordan_solve(A, b); sol <- .tup[[1]]; params <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .untranslated <- TRUE }, .mge)), silent = TRUE)
})

