test_that("reductions: test_row_op matches SymPy", {
  try(utils::capture.output(evalq({ e <- eye(3) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ elementary_row_op(e, "abc") }, .mge)), "ERR ValueError: Unknown row operation 'abc'. Valid col operations are 'n->kn', 'n<->m', 'n->n+km'")
  expect_identical(.mgs(evalq({ elementary_row_op(e) }, .mge)), "ERR ValueError: For a row operation 'n->kn' you must provide the kwargs `row` and `k`")
  expect_identical(.mgs(evalq({ elementary_row_op(e, "n->kn", row = -5, k = 5) }, .mge)), "ERR ValueError: This matrix does not have a row '-5'")
  expect_identical(.mgs(evalq({ elementary_row_op(e, "n<->m", row1 = -5, row2 = 2) }, .mge)), "ERR ValueError: This matrix does not have a row '-5'")
  expect_identical(.mgs(evalq({ elementary_row_op(e, "n<->m", row1 = 2, row2 = -5) }, .mge)), "ERR ValueError: This matrix does not have a row '-5'")
  expect_identical(.mgs(evalq({ elementary_row_op(e, "n->n+km", row1 = -5, row2 = 2, k = 5) }, .mge)), "ERR ValueError: This matrix does not have a row '-5'")
  expect_identical(.mgs(evalq({ elementary_row_op(e, "n->n+km", row1 = 2, row2 = -5, k = 5) }, .mge)), "ERR ValueError: This matrix does not have a row '-5'")
  expect_identical(.mgs(evalq({ elementary_row_op(e, "n->n+km", row1 = 2, row2 = 2, k = 5) }, .mge)), "ERR ValueError: For a row operation 'n->n+km' `row` and `row2` must be different.")
  expect_identical(.mgs(evalq({ elementary_row_op(e, "n->kn", 1, 5) }, .mge)), "Matrix([[5, 0, 0], [0, 1, 0], [0, 0, 1]])")
  expect_identical(.mgs(evalq({ elementary_row_op(e, "n->kn", 2, 5) }, .mge)), "Matrix([[1, 0, 0], [0, 5, 0], [0, 0, 1]])")
  expect_identical(.mgs(evalq({ elementary_row_op(e, "n->kn", row = 2, k = 5) }, .mge)), "Matrix([[1, 0, 0], [0, 5, 0], [0, 0, 1]])")
  expect_identical(.mgs(evalq({ elementary_row_op(e, "n->kn", row1 = 2, k = 5) }, .mge)), "Matrix([[1, 0, 0], [0, 5, 0], [0, 0, 1]])")
  expect_identical(.mgs(evalq({ elementary_row_op(e, "n<->m", 1, 2) }, .mge)), "Matrix([[0, 1, 0], [1, 0, 0], [0, 0, 1]])")
  expect_identical(.mgs(evalq({ elementary_row_op(e, "n<->m", row1 = 1, row2 = 2) }, .mge)), "Matrix([[0, 1, 0], [1, 0, 0], [0, 0, 1]])")
  expect_identical(.mgs(evalq({ elementary_row_op(e, "n<->m", row = 1, row2 = 2) }, .mge)), "Matrix([[0, 1, 0], [1, 0, 0], [0, 0, 1]])")
  expect_identical(.mgs(evalq({ elementary_row_op(e, "n->n+km", 1, 5, 2) }, .mge)), "Matrix([[1, 5, 0], [0, 1, 0], [0, 0, 1]])")
  expect_identical(.mgs(evalq({ elementary_row_op(e, "n->n+km", row = 1, k = 5, row2 = 2) }, .mge)), "Matrix([[1, 5, 0], [0, 1, 0], [0, 0, 1]])")
  expect_identical(.mgs(evalq({ elementary_row_op(e, "n->n+km", row1 = 1, k = 5, row2 = 2) }, .mge)), "Matrix([[1, 5, 0], [0, 1, 0], [0, 0, 1]])")
  try(utils::capture.output(evalq({ a <- Matrix(2, 3, list(0) * 6) }, .mge)), silent = TRUE)
})

