# test_eigen
.mge <- .mgs_env()
test_that("eigen: test_eigen matches SymPy", {
  try(utils::capture.output(evalq({ R <- Rational }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ M <- eye(3) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ eigenvals(M, multiple = TRUE) }, .mge)), "[1, 1, 1]")
  expect_identical(.mgs(evalq({ eigenvects(M) }, .mge)), "[[1, 3, [Matrix([[1], [0], [0]]), Matrix([[0], [1], [0]]), Matrix([[0], [0], [1]])]]]")
  expect_identical(.mgs(evalq({ left_eigenvects(M) }, .mge)), "[[1, 3, [Matrix([[1, 0, 0]]), Matrix([[0, 1, 0]]), Matrix([[0, 0, 1]])]]]")
  try(utils::capture.output(evalq({ M <- Matrix(list(list(0, 1, 1), list(1, 0, 0), list(1, 1, 1))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ eigenvects(M) }, .mge)), "[[-1, 1, [Matrix([[-1], [1], [0]])]], [0, 1, [Matrix([[0], [-1], [1]])]], [2, 1, [Matrix([[2/3], [1/3], [1]])]]]")
  expect_identical(.mgs(evalq({ left_eigenvects(M) }, .mge)), "[[-1, 1, [Matrix([[-2, 1, 1]])]], [0, 1, [Matrix([[-1, -1, 1]])]], [2, 1, [Matrix([[1, 1, 1]])]]]")
  try(utils::capture.output(evalq({ a <- Symbol("a") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ M <- Matrix(list(list(a, 0), list(0, 1))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ M <- Matrix(list(list(1, -1), list(1, 3))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ eigenvects(M) }, .mge)), "[[2, 2, [Matrix([[-1], [1]])]]]")
  expect_identical(.mgs(evalq({ left_eigenvects(M) }, .mge)), "[[2, 2, [Matrix([[1, 1]])]]]")
  try(utils::capture.output(evalq({ M <- Matrix(list(list(1, 2, 3), list(4, 5, 6), list(7, 8, 9))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ a <- R(15, 2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ b <- 3 * (33^R(1, 2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ c <- R(13, 2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ d <- R(33, 8) + ((3 * b) / 8) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ e <- R(33, 8) - ((3 * b) / 8) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ r <- list(list(a - (b / 2), 1, list(Matrix(list(((12 + (24 / (c - (b / 2)))) / ((c - (b / 2)) * e)) + (3 / (c - (b / 2))), (6 + (12 / (c - (b / 2)))) / e, 1)))), list(0, 1, list(Matrix(list(1, -2, 1)))), list(a + (b / 2), 1, list(Matrix(list(((12 + (24 / (c + (b / 2)))) / ((c + (b / 2)) * d)) + (3 / (c + (b / 2))), (6 + (12 / (c + (b / 2)))) / d, 1))))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .untranslated <- TRUE }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ r <- eigenvects(M) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .untranslated <- TRUE }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ eps <- Symbol("eps", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ M <- Matrix(list(list(Abs(eps), sym_I * eps), list((-sym_I) * eps, Abs(eps)))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ eigenvects(M) }, .mge)), "[[0, 1, [Matrix([[-I*eps/Abs(eps)], [1]])]], [2*Abs(eps), 1, [Matrix([[I*eps/Abs(eps)], [1]])]]]")
  expect_identical(.mgs(evalq({ left_eigenvects(M) }, .mge)), "[[0, 1, [Matrix([[I*eps/Abs(eps), 1]])]], [2*Abs(eps), 1, [Matrix([[-I*eps/Abs(eps), 1]])]]]")
  try(utils::capture.output(evalq({ M <- Matrix(3, 3, list(1, 2, 0, 0, 3, 0, 2, -4, 2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .untranslated <- TRUE }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .untranslated <- TRUE }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ M <- Matrix(list(list(Rational(1, 4), 1), list(1, 1))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ eigenvects(M) }, .mge)), "[[5/8 - sqrt(73)/8, 1, [Matrix([[-sqrt(73)/8 - 3/8], [1]])]], [5/8 + sqrt(73)/8, 1, [Matrix([[-3/8 + sqrt(73)/8], [1]])]]]")
  expect_identical(.mgs(evalq({ eigenvals(Matrix(list()), multiple = TRUE) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ eigenvects(Matrix(list())) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ eigenvals(Matrix(list(list(1, 2), list(0, 4), list(0, 0)))) }, .mge)), "ERR NonSquareMatrixError: Matrix([[1, 2], [0, 4], [0, 0]]) must be a square matrix.")
  expect_identical(.mgs(evalq({ eigenvals(Matrix(list(list(1, 0), list(3, 4), list(5, 6)))) }, .mge)), "ERR NonSquareMatrixError: Matrix([[1, 0], [3, 4], [5, 6]]) must be a square matrix.")
  expect_identical(.mgs(evalq({ eigenvals(Matrix(list(list(1, 2, 3), list(0, 5, 6)))) }, .mge)), "ERR NonSquareMatrixError: Matrix([[1, 2, 3], [0, 5, 6]]) must be a square matrix.")
  expect_identical(.mgs(evalq({ eigenvals(Matrix(list(list(1, 0, 0), list(4, 5, 0)))) }, .mge)), "ERR NonSquareMatrixError: Matrix([[1, 0, 0], [4, 5, 0]]) must be a square matrix.")
  expect_identical(.mgs(evalq({ eigenvals(Matrix(list(list(1, 2, 3), list(0, 5, 6))), error_when_incomplete = FALSE) }, .mge)), "ERR NonSquareMatrixError: Matrix([[1, 2, 3], [0, 5, 6]]) must be a square matrix.")
  expect_identical(.mgs(evalq({ eigenvals(Matrix(list(list(1, 0, 0), list(4, 5, 0))), error_when_incomplete = FALSE) }, .mge)), "ERR NonSquareMatrixError: Matrix([[1, 0, 0], [4, 5, 0]]) must be a square matrix.")
  try(utils::capture.output(evalq({ m <- Matrix(list(list(1, 2), list(3, 4))) }, .mge)), silent = TRUE)
})

test_that("eigen: test_diagonalize matches SymPy", {
  try(utils::capture.output(evalq({ m <- Matrix(2, 2, list(0, -1, 1, 0)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ diagonalize(m, reals_only = TRUE) }, .mge)), "ERR MatrixError: Matrix is not diagonalizable")
  try(utils::capture.output(evalq({ .tup <- diagonalize(m); P <- .tup[[1]]; D <- .tup[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_diagonal(D) }, .mge)), "True")
  expect_identical(.mgs(evalq({ D }, .mge)), "Matrix([[-I, 0], [0, I]])")
  try(utils::capture.output(evalq({ m <- Matrix(2, 2, list(0, 0.5, 0.5, 0)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- diagonalize(m); P <- .tup[[1]]; D <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- diagonalize(m, reals_only = TRUE); ._ <- .tup[[1]]; D2 <- .tup[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ D }, .mge)), "Matrix([[-0.500000000000000, 0], [0, 0.500000000000000]])")
  try(utils::capture.output(evalq({ m <- Matrix(list(list(0, 1, 0, 0), list(1, 0, 0, 0.002), list(0.002, 0, 0, 1), list(0, 0, 1, 0))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- diagonalize(m); P <- .tup[[1]]; D <- .tup[[2]] }, .mge)), silent = TRUE)
})

