test_that("eigen: test_jordan_form matches SymPy", {
  try(utils::capture.output(evalq({ m <- Matrix(3, 2, list(-3, 1, -3, 20, 3, 10)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ jordan_form(m) }, .mge)), "ERR NonSquareMatrixError: Only square matrices have Jordan forms")
  try(utils::capture.output(evalq({ m <- Matrix(4, 4, list(2, 1, 0, 0, 0, 2, 1, 0, 0, 0, 2, 0, 0, 0, 0, 2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- jordan_form(m); P <- .tup[[1]]; J <- .tup[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ m }, .mge)), "Matrix([[2, 1, 0, 0], [0, 2, 1, 0], [0, 0, 2, 0], [0, 0, 0, 2]])")
  try(utils::capture.output(evalq({ m <- Matrix(4, 4, list(2, 1, 0, 0, 0, 2, 0, 0, 0, 0, 2, 1, 0, 0, 0, 2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- jordan_form(m); P <- .tup[[1]]; J <- .tup[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ m }, .mge)), "Matrix([[2, 1, 0, 0], [0, 2, 0, 0], [0, 0, 2, 1], [0, 0, 0, 2]])")
  try(utils::capture.output(evalq({ A <- Matrix(list(list(2, 4, 1, 0), list(-4, 2, 0, 1), list(0, 0, 2, 4), list(0, 0, -4, 2))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- jordan_form(A); P <- .tup[[1]]; J <- .tup[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ simplify((P %*% J) %*% inverse(P)) }, .mge)), "Matrix([[2, 4, 1, 0], [-4, 2, 0, 1], [0, 0, 2, 4], [0, 0, -4, 2]])")
  expect_identical(.mgs(evalq({ jordan_form(Matrix(1, 1, list(1))) }, .mge)), "[Matrix([[1]]), Matrix([[1]])]")
  expect_identical(.mgs(evalq({ jordan_form(Matrix(1, 1, list(1)), calc_transform = FALSE) }, .mge)), "Matrix([[1]])")
  try(utils::capture.output(evalq({ m <- Matrix(list(list(0.6875, 0.125 + (0.1875 * sqrt(S(3)))), list(0.125 + (0.1875 * sqrt(S(3))), 0.3125))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- jordan_form(m); P <- .tup[[1]]; J <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(-3, 1, 2), list(1, -1, 0), list(1, 0, -2))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- jordan_form(A); P <- .tup[[1]]; J <- .tup[[2]] }, .mge)), silent = TRUE)
})

test_that("eigen: test_singular_values matches SymPy", {
  try(utils::capture.output(evalq({ x <- Symbol("x", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- Matrix(list(list(0, 1 * sym_I), list(2, 0))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ singular_values(A) }, .mge)), "[2, 1]")
