test_that("eigen: test_definite matches SymPy", {
  try(utils::capture.output(evalq({ m <- Matrix(list(list(2, -1, 0), list(-1, 2, -1), list(0, -1, 2))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_positive_definite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_positive_semidefinite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_negative_definite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_negative_semidefinite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_indefinite(m) }, .mge)), "False")
  try(utils::capture.output(evalq({ m <- Matrix(list(list(5, 4), list(4, 5))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_positive_definite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_positive_semidefinite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_negative_definite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_negative_semidefinite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_indefinite(m) }, .mge)), "False")
  try(utils::capture.output(evalq({ m <- Matrix(list(list(2, -1, -1), list(-1, 2, -1), list(-1, -1, 2))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_positive_definite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_positive_semidefinite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_negative_definite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_negative_semidefinite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_indefinite(m) }, .mge)), "False")
  try(utils::capture.output(evalq({ m <- Matrix(list(list(1, 2), list(2, 4))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_positive_definite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_positive_semidefinite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_negative_definite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_negative_semidefinite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_indefinite(m) }, .mge)), "False")
  try(utils::capture.output(evalq({ m <- Matrix(list(list(2, 3), list(4, 8))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_positive_definite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_positive_semidefinite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_negative_definite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_negative_semidefinite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_indefinite(m) }, .mge)), "False")
  try(utils::capture.output(evalq({ m <- Matrix(list(list(1, 2 * sym_I), list(-sym_I, 4))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_positive_definite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_positive_semidefinite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_negative_definite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_negative_semidefinite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_indefinite(m) }, .mge)), "False")
  try(utils::capture.output(evalq({ a <- Symbol("a", positive = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ b <- Symbol("b", negative = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(list(list(a, 0, 0), list(0, a, 0), list(0, 0, a))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_positive_definite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_positive_semidefinite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_negative_definite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_negative_semidefinite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_indefinite(m) }, .mge)), "False")
  try(utils::capture.output(evalq({ m <- Matrix(list(list(b, 0, 0), list(0, b, 0), list(0, 0, b))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_positive_definite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_positive_semidefinite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_negative_definite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_negative_semidefinite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_indefinite(m) }, .mge)), "False")
  try(utils::capture.output(evalq({ m <- Matrix(list(list(a, 0), list(0, b))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_positive_definite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_positive_semidefinite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_negative_definite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_negative_semidefinite(m) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_indefinite(m) }, .mge)), "True")
  try(utils::capture.output(evalq({ m <- Matrix(list(list(0.0228202735623867, 0.00518748979085398, -0.0743036351048907, -0.00709135324903921), list(0.00518748979085398, 0.034904535978635, 0.0830317991056637, 0.00233147902806909), list(-0.0743036351048907, 0.0830317991056637, 1.15859676366277, 0.340359081555988), list(-0.00709135324903921, 0.00233147902806909, 0.340359081555988, 0.928147644848199))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_positive_definite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_positive_semidefinite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_indefinite(m) }, .mge)), "False")
  try(utils::capture.output(evalq({ m <- Matrix(list(list(0, 0, 0), list(0, 1, 2), list(0, 2, 1))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ !is_positive_definite(m) }, .mge)), "True")
  expect_identical(.mgs(evalq({ !is_positive_semidefinite(m) }, .mge)), "True")
})

