test_that("eigen: test_issue_19210 matches SymPy", {
  try(utils::capture.output(evalq({ t <- Symbol("t") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ H <- Matrix(list(list(3, 0, 0, 0), list(0, 1, 2, 0), list(0, 2, 2, 0), list(0, 0, 0, 4))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ A <- jordan_form(((-sym_I) * H) * t) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ A }, .mge)), "[Matrix([[0, 1, 0, 0], [0, 0, -4/(-1 + sqrt(17)), 4/(1 + sqrt(17))], [0, 0, 1, 1], [1, 0, 0, 0]]), Matrix([[-4*I*t, 0, 0, 0], [0, -3*I*t, 0, 0], [0, 0, t*(-3*I/2 + sqrt(17)*I/2), 0], [0, 0, 0, t*(-sqrt(17)*I/2 - 3*I/2)]])]")
})

test_that("eigen: test_issue_20752 matches SymPy", {
  try(utils::capture.output(evalq({ b <- Symbol("b", nonzero = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(list(list(0, 0, 0), list(0, b, 0), list(0, 0, b))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_positive_semidefinite(m) }, .mge)), "None")
})

test_that("eigen: test_issue_28793 matches SymPy", {
  try(utils::capture.output(evalq({ A <- Matrix(list(list(((((3 * sqrt(S(2))) * sym_I) * sym_pi) * (1 + sqrt(S(2)))) / 4, 0, (((-sqrt(S(2))) * sym_I) * sym_pi) / 4, 0, 0, 0, 0, 0), list(0, (((sqrt(S(2)) * sym_I) * sym_pi) * (1 + sqrt(S(2)))) / 2, 0, ((-sym_I) * sym_pi) / 2, 0, 0, 0, 0), list((((-sqrt(S(2))) * sym_I) * sym_pi) / 4, 0, ((((3 * sqrt(S(2))) * sym_I) * sym_pi) * (1 + sqrt(S(2)))) / 4, 0, 0, 0, 0, 0), list(0, ((-sym_I) * sym_pi) / 2, 0, (((sqrt(S(2)) * sym_I) * sym_pi) * (1 + sqrt(S(2)))) / 2, 0, 0, ((-sym_I) * sym_pi) / 2, 0), list(0, 0, 0, 0, (((sqrt(S(2)) * sym_I) * sym_pi) * (1 + sqrt(S(2)))) / 2, 0, 0, 0), list(0, 0, 0, 0, 0, (((sqrt(S(2)) * sym_I) * sym_pi) * (1 + sqrt(S(2)))) / 4, 0, (((-sqrt(S(2))) * sym_I) * sym_pi) / 4), list(0, 0, 0, ((-sym_I) * sym_pi) / 2, 0, 0, (((sqrt(S(2)) * sym_I) * sym_pi) * (1 + sqrt(S(2)))) / 2, 0), list(0, 0, 0, 0, 0, (((-sqrt(S(2))) * sym_I) * sym_pi) / 4, 0, (((sqrt(S(2)) * sym_I) * sym_pi) * (1 + sqrt(S(2)))) / 4))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ z <- Symbol("z") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ expected <- (((((((((z^8) + ((z^7) * ((((-8) * sym_I) * sym_pi) - (((4 * sqrt(S(2))) * sym_I) * sym_pi)))) + ((z^6) * ((((-81) * (sym_pi^2)) / 2) - (((55 * sqrt(S(2))) * (sym_pi^2)) / 2)))) + ((z^5) * (((((181 * sqrt(S(2))) * sym_I) * (sym_pi^3)) / 2) + ((128 * sym_I) * (sym_pi^3))))) + ((z^4) * (((3991 * (sym_pi^4)) / 16) + (((1413 * sqrt(S(2))) * (sym_pi^4)) / 8)))) + ((z^3) * ((((((-1699) * sqrt(S(2))) * sym_I) * (sym_pi^5)) / 8) - (((1201 * sym_I) * (sym_pi^5)) / 4)))) + ((z^2) * ((((-6927) * (sym_pi^6)) / 32) - (((2449 * sqrt(S(2))) * (sym_pi^6)) / 16)))) + (z * (((((1919 * sqrt(S(2))) * sym_I) * (sym_pi^7)) / 32) + (((1357 * sym_I) * (sym_pi^7)) / 16)))) + (((309 * sqrt(S(2))) * (sym_pi^8)) / 32)) + ((437 * (sym_pi^8)) / 32) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ vals <- eigenvals(A) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ eigenvects(A) }, .mge)), "[[I*pi/2, 1, [Matrix([[0], [0], [0], [0], [0], [1], [0], [1]])]], [I*pi, 1, [Matrix([[0], [1], [0], [sqrt(2)], [0], [0], [1], [0]])]], [I*pi/2 + sqrt(2)*I*pi/2, 1, [Matrix([[0], [0], [0], [0], [0], [-1], [0], [1]])]], [I*pi + sqrt(2)*I*pi, 1, [Matrix([[0], [1], [0], [-sqrt(2)], [0], [0], [1], [0]])]], [-sqrt(2)*I*pi/4 + 3*I*pi*(sqrt(2) + 2)/4, 1, [Matrix([[1], [0], [1], [0], [0], [0], [0], [0]])]], [sqrt(2)*I*pi/4 + 3*I*pi*(sqrt(2) + 2)/4, 1, [Matrix([[-1], [0], [1], [0], [0], [0], [0], [0]])]], [sqrt(2)*I*pi/2 + I*pi, 2, [Matrix([[0], [0], [0], [0], [1], [0], [0], [0]]), Matrix([[0], [-1], [0], [0], [0], [0], [1], [0]])]]]")
  try(utils::capture.output(evalq({ .tup <- jordan_form(A); P <- .tup[[1]]; J <- .tup[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ det(P) }, .mge)), "16*sqrt(2)")
  expect_identical(.mgs(evalq({ expand((P %*% J) %*% inverse(P)) }, .mge)), "Matrix([[3*sqrt(2)*I*pi/4 + 3*I*pi/2, 0, -sqrt(2)*I*pi/4, 0, 0, 0, 0, 0], [0, sqrt(2)*I*pi/2 + I*pi, 0, -I*pi/2, 0, 0, 0, 0], [-sqrt(2)*I*pi/4, 0, 3*sqrt(2)*I*pi/4 + 3*I*pi/2, 0, 0, 0, 0, 0], [0, -I*pi/2, 0, sqrt(2)*I*pi/2 + I*pi, 0, 0, -I*pi/2, 0], [0, 0, 0, 0, sqrt(2)*I*pi/2 + I*pi, 0, 0, 0], [0, 0, 0, 0, 0, sqrt(2)*I*pi/4 + I*pi/2, 0, -sqrt(2)*I*pi/4], [0, 0, 0, -I*pi/2, 0, 0, sqrt(2)*I*pi/2 + I*pi, 0], [0, 0, 0, 0, 0, -sqrt(2)*I*pi/4, 0, sqrt(2)*I*pi/4 + I*pi/2]])")
})

# test_graph
.mge <- .mgs_env()
test_that("graph: test_strongly_connected_components matches SymPy", {
  try(utils::capture.output(evalq({ M <- Matrix(list(list(11, 14, 10, 0, 15, 0), list(0, 44, 0, 0, 45, 0), list(1, 4, 0, 0, 5, 0), list(0, 0, 0, 22, 0, 23), list(0, 54, 0, 0, 55, 0), list(0, 0, 0, 32, 0, 33))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ scc <- .zb_cc(strongly_connected_components(M)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ scc }, .mge)), "[[1, 4], [0, 2], [3, 5]]")
  try(utils::capture.output(evalq({ .tup <- strongly_connected_components_decomposition(M); P <- .tup[[1]]; B <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p <- Permutation(list(1, 4, 0, 2, 3, 5)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ B }, .mge)), "Matrix([\\n[Matrix([\\n[44, 45],\\n[54, 55]]),     Matrix([\\n[0, 0],\\n[0, 0]]),     Matrix([\\n[0, 0],\\n[0, 0]])],\\n[Matrix([\\n[14, 15],\\n[ 4,  5]]), Matrix([\\n[11, 10],\\n[ 1,  0]]),     Matrix([\\n[0, 0],\\n[0, 0]])],\\n[    Matrix([\\n[0, 0],\\n[0, 0]]),     Matrix([\\n[0, 0],\\n[0, 0]]), Matrix([\\n[22, 23],\\n[32, 33]])]])")
  try(utils::capture.output(evalq({ P <- as_explicit(P) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ B <- as_explicit(B) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ (t(P) %*% B) %*% P }, .mge)), "Matrix([[11, 14, 10, 0, 15, 0], [0, 44, 0, 0, 45, 0], [1, 4, 0, 0, 5, 0], [0, 0, 0, 22, 0, 23], [0, 54, 0, 0, 55, 0], [0, 0, 0, 32, 0, 33]])")
  try(utils::capture.output(evalq({ .tup <- strongly_connected_components_decomposition(M, lower = FALSE); P <- .tup[[1]]; B <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p <- Permutation(list(3, 5, 0, 2, 1, 4)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ B }, .mge)), "Matrix([\\n[Matrix([\\n[22, 23],\\n[32, 33]]),     Matrix([\\n[0, 0],\\n[0, 0]]),     Matrix([\\n[0, 0],\\n[0, 0]])],\\n[    Matrix([\\n[0, 0],\\n[0, 0]]), Matrix([\\n[11, 10],\\n[ 1,  0]]), Matrix([\\n[14, 15],\\n[ 4,  5]])],\\n[    Matrix([\\n[0, 0],\\n[0, 0]]),     Matrix([\\n[0, 0],\\n[0, 0]]), Matrix([\\n[44, 45],\\n[54, 55]])]])")
  try(utils::capture.output(evalq({ P <- as_explicit(P) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ B <- as_explicit(B) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ (t(P) %*% B) %*% P }, .mge)), "Matrix([[11, 14, 10, 0, 15, 0], [0, 44, 0, 0, 45, 0], [1, 4, 0, 0, 5, 0], [0, 0, 0, 22, 0, 23], [0, 54, 0, 0, 55, 0], [0, 0, 0, 32, 0, 33]])")
})

# test_determinant
.mge <- .mgs_env()
test_that("determinant: test_det matches SymPy", {
  try(utils::capture.output(evalq({ a <- Matrix(2, 3, list(1, 2, 3, 4, 5, 6)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ det(a) }, .mge)), "ERR NonSquareMatrixError: ")
  try(utils::capture.output(evalq({ z <- zeros_Determinant(2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ ey <- eye_Determinant(2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ x <- Symbol("x") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ a <- Matrix(0, 0, list()) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ b <- Matrix(1, 1, list(5)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ c <- Matrix(2, 2, list(1, 2, 3, 4)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ d <- Matrix(3, 3, list(1, 2, 3, 4, 5, 6, 7, 8, 8)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ e <- Matrix(4, 4, list(x, 1, 2, 3, 4, 5, 6, 7, 2, 9, 10, 11, 12, 13, 14, 14)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ f <- Matrix(3, 3, list(i, l, m, 0, j, n, 0, 0, k)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ g <- Matrix(3, 3, list(i, 0, 0, l, j, 0, m, n, k)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ h <- Matrix(3, 3, list(x^3, 0, 0, i, x^(-1), 0, j, k, x^(-2))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ det(a) }, .mge)), "1")
  expect_identical(.mgs(evalq({ det(b) }, .mge)), "5")
  expect_identical(.mgs(evalq({ det(c) }, .mge)), "-2")
  expect_identical(.mgs(evalq({ det(d) }, .mge)), "3")
  expect_identical(.mgs(evalq({ det(e) }, .mge)), "4*x - 24")
  expect_identical(.mgs(evalq({ det(e, method = "domain-ge") }, .mge)), "4*x - 24")
  expect_identical(.mgs(evalq({ det(e, method = "bareiss") }, .mge)), "4*x - 24")
  expect_identical(.mgs(evalq({ det(e, method = "berkowitz") }, .mge)), "4*x - 24")
  expect_identical(.mgs(evalq({ det(e, iszerofunc = "test") }, .mge)), "ERR ValueError: Zero testing method 'test' unrecognized")
})

