test_that("determinant: test_adjugate matches SymPy", {
  try(utils::capture.output(evalq({ x <- Symbol("x") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ e <- Matrix(4, 4, list(x, 1, 2, 3, 4, 5, 6, 7, 2, 9, 10, 11, 12, 13, 14, 14)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ adj <- Matrix(list(list(4, -8, 4, 0), list(76, ((-14) * x) - 68, (14 * x) - 8, ((-4) * x) + 24), list(-122, (17 * x) + 142, ((-21) * x) + 4, (8 * x) - 48), list(48, ((-4) * x) - 72, 8 * x, ((-4) * x) + 24))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ adjugate(e) }, .mge)), "Matrix([[4, -8, 4, 0], [76, -14*x - 68, 14*x - 8, 24 - 4*x], [-122, 17*x + 142, 4 - 21*x, 8*x - 48], [48, -4*x - 72, 8*x, 24 - 4*x]])")
  expect_identical(.mgs(evalq({ adjugate(e, method = "bareiss") }, .mge)), "Matrix([[4, -8, 4, 0], [76, -14*x - 68, 14*x - 8, 24 - 4*x], [-122, 17*x + 142, 4 - 21*x, 8*x - 48], [48, -4*x - 72, 8*x, 24 - 4*x]])")
  expect_identical(.mgs(evalq({ adjugate(e, method = "berkowitz") }, .mge)), "Matrix([[4, -8, 4, 0], [76, -14*x - 68, 14*x - 8, 24 - 4*x], [-122, 17*x + 142, 4 - 21*x, 8*x - 48], [48, -4*x - 72, 8*x, 24 - 4*x]])")
  expect_identical(.mgs(evalq({ adjugate(e, method = "bird") }, .mge)), "Matrix([[4, -8, 4, 0], [76, -14*x - 68, 14*x - 8, 24 - 4*x], [-122, 17*x + 142, 4 - 21*x, 8*x - 48], [48, -4*x - 72, 8*x, 24 - 4*x]])")
  expect_identical(.mgs(evalq({ adjugate(e, method = "laplace") }, .mge)), "Matrix([[4, -8, 4, 0], [76, -14*x - 68, 14*x - 8, 24 - 4*x], [-122, 17*x + 142, 4 - 21*x, 8*x - 48], [48, -4*x - 72, 8*x, 24 - 4*x]])")
  try(utils::capture.output(evalq({ a <- Matrix(2, 3, list(1, 2, 3, 4, 5, 6)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ adjugate(a) }, .mge)), "ERR NonSquareMatrixError: ")
})

test_that("determinant: test_util matches SymPy", {
