  try(utils::capture.output(evalq({ v2 <- Matrix(1, 3, list(3, 4, 5)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ norm_matrix(v1) }, .mge)), "sqrt(14)")
