  expect_identical(.mgs(evalq({ ones(1, 2) }, .mge)), "Matrix([[1, 1]])")
  expect_identical(.mgs(evalq({ identity(v1) }, .mge)), "Matrix([[1, 2, 3]])")
  expect_identical(.mgs(evalq({ eye(3) }, .mge)), "Matrix([[1, 0, 0], [0, 1, 0], [0, 0, 1]])")
  try(utils::capture.output(evalq({ test <- Matrix(list(list(1, 3, 2), list(2, 6, 3), list(2, 3, 6))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ cofactor_matrix(test) }, .mge)), "Matrix([[27, -6, -6], [-12, 2, 3], [-3, 1, 0]])")
  try(utils::capture.output(evalq({ test <- Matrix(list(list(1, 2, 3), list(4, 5, 6), list(7, 8, 9))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ cofactor_matrix(test) }, .mge)), "Matrix([[-3, 6, -3], [6, -12, 6], [-3, 6, -3]])")
})

test_that("determinant: test_cofactor_and_minors matches SymPy", {
  try(utils::capture.output(evalq({ x <- Symbol("x") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ e <- Matrix(4, 4, list(x, 1, 2, 3, 4, 5, 6, 7, 2, 9, 10, 11, 12, 13, 14, 14)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Matrix(list(list(x, 1, 3), list(2, 9, 11), list(12, 13, 14))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ cm <- Matrix(list(list(4, 76, -122, 48), list(-8, ((-14) * x) - 68, (17 * x) + 142, ((-4) * x) - 72), list(4, (14 * x) - 8, ((-21) * x) + 4, 8 * x), list(0, ((-4) * x) + 24, (8 * x) - 48, ((-4) * x) + 24))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ sub <- Matrix(list(list(x, 1, 2), list(4, 5, 6), list(2, 9, 10))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ minor_submatrix(e, 2, 3) }, .mge)), "Matrix([[x, 1, 3], [2, 9, 11], [12, 13, 14]])")
  expect_identical(.mgs(evalq({ minor_submatrix(e, -1, -1) }, .mge)), "Matrix([[x, 1, 2], [4, 5, 6], [2, 9, 10]])")
  expect_identical(.mgs(evalq({ minor(e, 2, 3) }, .mge)), "-17*x - 142")
  expect_identical(.mgs(evalq({ cofactor(e, 2, 3) }, .mge)), "17*x + 142")
  expect_identical(.mgs(evalq({ cofactor_matrix(e) }, .mge)), "Matrix([[4, 76, -122, 48], [-8, -14*x - 68, 17*x + 142, -4*x - 72], [4, 14*x - 8, 4 - 21*x, 8*x], [0, 24 - 4*x, 8*x - 48, 24 - 4*x]])")
  expect_identical(.mgs(evalq({ cofactor_matrix(e, method = "bareiss") }, .mge)), "Matrix([[4, 76, -122, 48], [-8, -14*x - 68, 17*x + 142, -4*x - 72], [4, 14*x - 8, 4 - 21*x, 8*x], [0, 24 - 4*x, 8*x - 48, 24 - 4*x]])")
  expect_identical(.mgs(evalq({ cofactor_matrix(e, method = "berkowitz") }, .mge)), "Matrix([[4, 76, -122, 48], [-8, -14*x - 68, 17*x + 142, -4*x - 72], [4, 14*x - 8, 4 - 21*x, 8*x], [0, 24 - 4*x, 8*x - 48, 24 - 4*x]])")
  expect_identical(.mgs(evalq({ cofactor_matrix(e, method = "bird") }, .mge)), "Matrix([[4, 76, -122, 48], [-8, -14*x - 68, 17*x + 142, -4*x - 72], [4, 14*x - 8, 4 - 21*x, 8*x], [0, 24 - 4*x, 8*x - 48, 24 - 4*x]])")
  expect_identical(.mgs(evalq({ cofactor_matrix(e, method = "laplace") }, .mge)), "Matrix([[4, 76, -122, 48], [-8, -14*x - 68, 17*x + 142, -4*x - 72], [4, 14*x - 8, 4 - 21*x, 8*x], [0, 24 - 4*x, 8*x - 48, 24 - 4*x]])")
  expect_identical(.mgs(evalq({ minor_submatrix(e, 5, 6) }, .mge)), "ERR ValueError: `i` and `j` must satisfy 0 <= i < ``M.rows`` (4)and 0 <= j < ``M.cols`` (4).")
  try(utils::capture.output(evalq({ a <- Matrix(2, 3, list(1, 2, 3, 4, 5, 6)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ minor_submatrix(a, 1, 1) }, .mge)), "Matrix([[5, 6]])")
  expect_identical(.mgs(evalq({ minor_submatrix(Matrix(0, 0, list()), 1, 1) }, .mge)), "ERR ValueError: `i` and `j` must satisfy 0 <= i < ``M.rows`` (0)and 0 <= j < ``M.cols`` (0).")
  expect_identical(.mgs(evalq({ cofactor(a, 1, 1) }, .mge)), "ERR NonSquareMatrixError: ")
  expect_identical(.mgs(evalq({ minor(a, 1, 1) }, .mge)), "ERR NonSquareMatrixError: ")
  expect_identical(.mgs(evalq({ cofactor_matrix(a) }, .mge)), "ERR NonSquareMatrixError: ")
})

