# test_point
.mge <- .mgs_env()
test_that("point: test_point matches SymPy", {
  try(utils::capture.output(evalq({ x <- Symbol("x", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ y <- Symbol("y", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ x1 <- Symbol("x1", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ x2 <- Symbol("x2", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ y1 <- Symbol("y1", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ y2 <- Symbol("y2", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ half <- S_Half }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p1 <- Point(x1, x2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2 <- Point(y1, y2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p3 <- Point(0, 0) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p4 <- Point(1, 1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p5 <- Point(0, 1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ line <- Line(Point(1, 0), slope = 1) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ contains(p1, p1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ !contains(p2, p1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ point_y(p2) }, .mge)), "y2")
  expect_identical(.mgs(evalq({ p3 + p4 }, .mge)), "Point2D(1, 1)")
  expect_identical(.mgs(evalq({ p2 - p1 }, .mge)), "Point2D(-x1 + y1, -x2 + y2)")
  expect_identical(.mgs(evalq({ -p2 }, .mge)), "Point2D(-y1, -y2)")
  expect_identical(.mgs(evalq({ Point(1) }, .mge)), "ERR TypeError: \\nExpecting sequence of coordinates, not `int`")
  expect_identical(.mgs(evalq({ Point(list(1)) }, .mge)), "ERR ValueError: \\nPoint requires 2 or more coordinates or keyword `dim` > 1.")
  expect_identical(.mgs(evalq({ Point(3, sym_I) }, .mge)), "ERR ValueError: Imaginary coordinates are not permitted.")
  expect_identical(.mgs(evalq({ Point(2 * sym_I, sym_I) }, .mge)), "ERR ValueError: Imaginary coordinates are not permitted.")
  expect_identical(.mgs(evalq({ Point(3 + sym_I, sym_I) }, .mge)), "ERR ValueError: Imaginary coordinates are not permitted.")
  expect_identical(.mgs(evalq({ Point(34.05, sqrt(S(3))) }, .mge)), "Point2D(681/20, sqrt(3))")
  expect_identical(.mgs(evalq({ midpoint(p3, p4) }, .mge)), "Point2D(1/2, 1/2)")
  expect_identical(.mgs(evalq({ midpoint(p1, p4) }, .mge)), "Point2D(x1/2 + 1/2, x2/2 + 1/2)")
  expect_identical(.mgs(evalq({ midpoint(p2, p2) }, .mge)), "Point2D(y1, y2)")
  expect_identical(.mgs(evalq({ midpoint(p2, p2) }, .mge)), "Point2D(y1, y2)")
  expect_identical(.mgs(evalq({ origin(p1) }, .mge)), "Point2D(0, 0)")
  expect_identical(.mgs(evalq({ distance(p3, p4) }, .mge)), "sqrt(2)")
  expect_identical(.mgs(evalq({ distance(p1, p1) }, .mge)), "0")
  expect_identical(.mgs(evalq({ distance(p3, p2) }, .mge)), "sqrt(y1^2 + y2^2)")
  expect_identical(.mgs(evalq({ distance(p1, 0) }, .mge)), "ERR TypeError: not recognized as a GeometricEntity: <class 'int'>")
  expect_identical(.mgs(evalq({ distance(p1, line) }, .mge)), "sqrt((-x1/2 + x2/2 + 1/2)^2 + (x1/2 - x2/2 - 1/2)^2)")
  expect_identical(.mgs(evalq({ distance(p4, line) }, .mge)), "sqrt(2)/2")
  expect_identical(.mgs(evalq({ taxicab_distance(p4, p3) }, .mge)), "2")
  expect_identical(.mgs(evalq({ canberra_distance(p4, p5) }, .mge)), "1")
  expect_identical(.mgs(evalq({ canberra_distance(p3, p3) }, .mge)), "ERR ValueError: Cannot project to the zero vector.")
  try(utils::capture.output(evalq({ p1_1 <- Point(x1, x1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p1_2 <- Point(y2, y2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p1_3 <- Point(x1 + 1, x1) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_collinear(p3) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_collinear(p3) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_collinear(p3, p4) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_collinear(p3, p4, p1_1, p1_2) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_collinear(p3, p4, p1_1, p1_3) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_collinear(p3, p3, p4, p5) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_collinear(line) }, .mge)), "ERR TypeError: \\nExpecting sequence of coordinates, not `Line2D`")
  expect_identical(.mgs(evalq({ is_collinear(p1_1, line) }, .mge)), "ERR TypeError: \\nExpecting sequence of coordinates, not `Line2D`")
  expect_identical(.mgs(evalq({ intersection(p3, Point(0, 0)) }, .mge)), "[Point2D(0, 0)]")
  expect_identical(.mgs(evalq({ intersection(p3, p4) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ intersection(p3, line) }, .mge)), "[]")
  try(utils::capture.output(evalq({ x_pos <- Symbol("x", positive = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2_1 <- Point(x_pos, 0) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2_2 <- Point(0, x_pos) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2_3 <- Point(-x_pos, 0) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2_4 <- Point(0, -x_pos) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2_5 <- Point(x_pos, 5) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_concyclic(p2_1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_concyclic(p2_1, p2_2) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_concyclic(p2_1, p2_2, p2_3, p2_4) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_concyclic(p4, p4 * 2, p4 * 3) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_concyclic(Point(0, 0), list(1, 1), list(2, 2), list(2, 1)) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_concyclic(Point(0, 0, 0, 0), Point(1, 0, 0, 0), Point(1, 1, 0, 0), Point(1, 1, 1, 0)) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_scalar_multiple(p1, p1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_scalar_multiple(p1, 2 * p1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ !is_scalar_multiple(p1, p2) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_scalar_multiple(Point(1, 1), list(-1, -1)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_scalar_multiple(Point(0, 0), list(0, -1)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ orthogonal_direction(Point(0, 1)) }, .mge)), "Point2D(1, 0)")
  expect_identical(.mgs(evalq({ orthogonal_direction(Point(1, 0)) }, .mge)), "Point2D(0, 1)")
  expect_identical(.mgs(evalq({ is_zero(p1) }, .mge)), "None")
  expect_identical(.mgs(evalq({ is_zero(p3) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_zero(p4) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_nonzero(p1) }, .mge)), "None")
  expect_identical(.mgs(evalq({ is_nonzero(p3) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_nonzero(p4) }, .mge)), "True")
  expect_identical(.mgs(evalq({ geo_scale(p4, 2, 3) }, .mge)), "Point2D(2, 3)")
  expect_identical(.mgs(evalq({ geo_scale(p3, 2, 3) }, .mge)), "Point2D(0, 0)")
  expect_identical(.mgs(evalq({ geo_rotate(p4, sym_pi, Point(0.5, 0.5)) }, .mge)), "Point2D(0, 0)")
  expect_identical(.mgs(evalq({ p4 * 5 }, .mge)), "Point2D(5, 5)")
  expect_identical(.mgs(evalq({ p4 / 5 }, .mge)), "Point2D(1/5, 1/5)")
  expect_identical(.mgs(evalq({ 5 * p4 }, .mge)), "Point2D(5, 5)")
  expect_identical(.mgs(evalq({ Point(0, 0) + 10 }, .mge)), "ERR GeometryError: Don't know how to add 10 and a Point object")
  expect_identical(.mgs(evalq({ Point(x * (x - 1), y) - Point((x^2) - x, y + 1) }, .mge)), "Point2D(0, -1)")
  try(utils::capture.output(evalq({ .tup <- list(S_Half, Rational(1, 3)); a <- .tup[[1]]; b <- .tup[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ evalf(Point(a, b), 2) }, .mge)), "Point2D(0.5, 0.33)")
  expect_identical(.mgs(evalq({ Point(1, 2) + 1 }, .mge)), "ERR GeometryError: Don't know how to add 1 and a Point object")
  expect_identical(.mgs(evalq({ project(list(0, 1), list(1, 0)) }, .mge)), "Point2D(0, 0)")
  expect_identical(.mgs(evalq({ project(list(1, 1), list(1, 0)) }, .mge)), "Point2D(1, 0)")
  expect_identical(.mgs(evalq({ project(p1, Point(0, 0)) }, .mge)), "ERR ValueError: Cannot project to the zero vector.")
  try(utils::capture.output(evalq({ p <- Point(1, 0) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ geo_rotate(p, sym_pi / 2) }, .mge)), "Point2D(0, 1)")
  expect_identical(.mgs(evalq({ geo_rotate(p, sym_pi / 2, p) }, .mge)), "Point2D(1, 0)")
  try(utils::capture.output(evalq({ p <- Point(1, 1) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ geo_scale(p, 2, 3) }, .mge)), "Point2D(2, 3)")
  expect_identical(.mgs(evalq({ translate(p, 1, 2) }, .mge)), "Point2D(2, 3)")
  expect_identical(.mgs(evalq({ translate(p, 1) }, .mge)), "Point2D(2, 1)")
  expect_identical(.mgs(evalq({ translate(p, y = 1) }, .mge)), "Point2D(1, 2)")
  expect_identical(.mgs(evalq({ geo_transform(p3, p3) }, .mge)), "ERR ValueError: matrix must be a 3x3 matrix")
  expect_identical(.mgs(evalq({ geo_transform(p, Matrix(list(list(1, 0), list(0, 1)))) }, .mge)), "ERR ValueError: matrix must be a 3x3 matrix")
  expect_identical(.mgs(evalq({ contains(Point(0, 0, 0, 0), 0) }, .mge)), "True")
  expect_identical(.mgs(evalq({ !contains(Point(0, 0, 0, 0), 1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ affine_rank() }, .mge)), "-1")
})

test_that("point: test_point3D matches SymPy", {
  try(utils::capture.output(evalq({ x <- Symbol("x", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ y <- Symbol("y", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ x1 <- Symbol("x1", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ x2 <- Symbol("x2", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ x3 <- Symbol("x3", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ y1 <- Symbol("y1", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ y2 <- Symbol("y2", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ y3 <- Symbol("y3", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ half <- S_Half }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p1 <- Point3D(x1, x2, x3) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2 <- Point3D(y1, y2, y3) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p3 <- Point3D(0, 0, 0) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p4 <- Point3D(1, 1, 1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p5 <- Point3D(0, 1, 2) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ contains(p1, p1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ !contains(p2, p1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ point_y(p2) }, .mge)), "y2")
  expect_identical(.mgs(evalq({ p3 + p4 }, .mge)), "Point3D(1, 1, 1)")
  expect_identical(.mgs(evalq({ p2 - p1 }, .mge)), "Point3D(-x1 + y1, -x2 + y2, -x3 + y3)")
  expect_identical(.mgs(evalq({ -p2 }, .mge)), "Point3D(-y1, -y2, -y3)")
  expect_identical(.mgs(evalq({ Point(34.05, sqrt(S(3))) }, .mge)), "Point2D(681/20, sqrt(3))")
  expect_identical(.mgs(evalq({ midpoint(p3, p4) }, .mge)), "Point3D(1/2, 1/2, 1/2)")
  expect_identical(.mgs(evalq({ midpoint(p1, p4) }, .mge)), "Point3D(x1/2 + 1/2, x2/2 + 1/2, x3/2 + 1/2)")
  expect_identical(.mgs(evalq({ midpoint(p2, p2) }, .mge)), "Point3D(y1, y2, y3)")
  expect_identical(.mgs(evalq({ midpoint(p2, p2) }, .mge)), "Point3D(y1, y2, y3)")
  expect_identical(.mgs(evalq({ distance(p3, p4) }, .mge)), "sqrt(3)")
  expect_identical(.mgs(evalq({ distance(p1, p1) }, .mge)), "0")
  expect_identical(.mgs(evalq({ distance(p3, p2) }, .mge)), "sqrt(y1^2 + y2^2 + y3^2)")
  try(utils::capture.output(evalq({ p1_1 <- Point3D(x1, x1, x1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p1_2 <- Point3D(y2, y2, y2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p1_3 <- Point3D(x1 + 1, x1, x1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ are_collinear(p3) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ are_collinear(p3, p4) }, .mge)), "True")
  expect_identical(.mgs(evalq({ are_collinear(p3, p4, p1_1, p1_2) }, .mge)), "True")
  expect_identical(.mgs(evalq({ are_collinear(p3, p4, p1_1, p1_3) }, .mge)), "False")
  expect_identical(.mgs(evalq({ are_collinear(p3, p3, p4, p5) }, .mge)), "False")
  expect_identical(.mgs(evalq({ intersection(p3, Point3D(0, 0, 0)) }, .mge)), "[Point3D(0, 0, 0)]")
  expect_identical(.mgs(evalq({ intersection(p3, p4) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ p4 * 5 }, .mge)), "Point3D(5, 5, 5)")
  expect_identical(.mgs(evalq({ p4 / 5 }, .mge)), "Point3D(1/5, 1/5, 1/5)")
  expect_identical(.mgs(evalq({ 5 * p4 }, .mge)), "Point3D(5, 5, 5)")
  expect_identical(.mgs(evalq({ Point3D(0, 0, 0) + 10 }, .mge)), "ERR GeometryError: Don't know how to add 10 and a Point object")
  expect_identical(.mgs(evalq({ p1$coords }, .mge)), "[x1, x2, x3]")
  expect_identical(.mgs(evalq({ p2$coords }, .mge)), "[y1, y2, y3]")
  expect_identical(.mgs(evalq({ p3$coords }, .mge)), "[0, 0, 0]")
  expect_identical(.mgs(evalq({ p4$coords }, .mge)), "[1, 1, 1]")
  expect_identical(.mgs(evalq({ p5$coords }, .mge)), "[0, 1, 2]")
  expect_identical(.mgs(evalq({ point_x(p5) }, .mge)), "0")
  expect_identical(.mgs(evalq({ point_y(p5) }, .mge)), "1")
  expect_identical(.mgs(evalq({ point_z(p5) }, .mge)), "2")
  expect_identical(.mgs(evalq({ Point3D(x * (x - 1), y, 2) - Point3D((x^2) - x, y + 1, 1) }, .mge)), "Point3D(0, -1, 1)")
  try(utils::capture.output(evalq({ .tup <- list(S_Half, Rational(1, 3), Rational(1, 4)); a <- .tup[[1]]; b <- .tup[[2]]; c <- .tup[[3]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ evalf(Point3D(a, b, c), 2) }, .mge)), "Point3D(0.5, 0.33, 0.25)")
  expect_identical(.mgs(evalq({ Point3D(1, 2, 3) + 1 }, .mge)), "ERR GeometryError: Don't know how to add 1 and a Point object")
  try(utils::capture.output(evalq({ p <- Point3D(1, 1, 1) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ geo_scale(p, 2, 3) }, .mge)), "Point3D(2, 3, 1)")
  expect_identical(.mgs(evalq({ translate(p, 1, 2) }, .mge)), "Point3D(2, 3, 1)")
  expect_identical(.mgs(evalq({ translate(p, 1) }, .mge)), "Point3D(2, 1, 1)")
  expect_identical(.mgs(evalq({ translate(p, z = 1) }, .mge)), "Point3D(1, 1, 2)")
  expect_identical(.mgs(evalq({ identical((sym_args(Point3D(0.1, 0.2, evaluate = FALSE, on_morph = "ignore"))[[1]])$type, "Float") }, .mge)), "True")
  expect_identical(.mgs(evalq({ geo_length(p) }, .mge)), "0")
  expect_identical(.mgs(evalq({ geo_length(p1_1) }, .mge)), "0")
  expect_identical(.mgs(evalq({ geo_length(p1_2) }, .mge)), "0")
  expect_identical(.mgs(evalq({ are_collinear(p, x) }, .mge)), "ERR TypeError: \\nExpecting sequence of coordinates, not `Symbol`")
  expect_identical(.mgs(evalq({ .mg_point_are_coplanar() }, .mge)), "True")
  expect_identical(.mgs(evalq({ .mg_point_are_coplanar(list(1, 2, 0), list(1, 2, 0), list(1, 3, 0)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ .mg_point_are_coplanar(list(1, 2, 0), list(1, 2, 3)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ .mg_point_are_coplanar(list(1, 2, 0), list(1, 2, 3)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ .mg_point_are_coplanar(list(0, 0, 0), list(1, 1, 0), list(1, 1, 1), list(1, 2, 1)) }, .mge)), "False")
  try(utils::capture.output(evalq({ planar2 <- Point3D(1, -1, 1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ planar3 <- Point3D(-1, 1, 1) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ .mg_point_are_coplanar(p, planar2, planar3) }, .mge)), "True")
  expect_identical(.mgs(evalq({ .mg_point_are_coplanar(p, planar2, planar3, p3) }, .mge)), "False")
  expect_identical(.mgs(evalq({ .mg_point_are_coplanar(p, planar2) }, .mge)), "True")
  try(utils::capture.output(evalq({ planar2 <- Point3D(1, 1, 2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ planar3 <- Point3D(1, 1, 3) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ .mg_point_are_coplanar(p, planar2, planar3) }, .mge)), "True")
  try(utils::capture.output(evalq({ plane <- Plane(list(1, 2, 1), list(2, 1, 0), list(3, 1, 2)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ .mg_point_are_coplanar(Point(x, y), Point(x, x + y), Point(y, x + 2)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ intersection(planar2, Line3D(p, planar3)) }, .mge)), "[Point3D(1, 1, 2)]")
  expect_identical(.mgs(evalq({ geo_scale(planar2, 1, 1, 1) }, .mge)), "Point3D(1, 1, 2)")
  expect_identical(.mgs(evalq({ geo_scale(planar2, 2, 2, 2, planar3) }, .mge)), "Point3D(1, 1, 1)")
  expect_identical(.mgs(evalq({ geo_scale(planar2, 1, 1, 1, p3) }, .mge)), "Point3D(1, 1, 2)")
  try(utils::capture.output(evalq({ identity <- Matrix(list(list(1, 0, 0, 0), list(0, 1, 0, 0), list(0, 0, 1, 0), list(0, 0, 0, 1))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ geo_transform(p, identity) }, .mge)), "Point3D(1, 1, 1)")
  try(utils::capture.output(evalq({ trans <- Matrix(list(list(1, 0, 0, 1), list(0, 1, 0, 1), list(0, 0, 1, 1), list(0, 0, 0, 1))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ geo_transform(p, trans) }, .mge)), "Point3D(2, 2, 2)")
  expect_identical(.mgs(evalq({ geo_transform(p, p) }, .mge)), "ERR ValueError: matrix must be a 4x4 matrix")
  expect_identical(.mgs(evalq({ geo_transform(p, Matrix(list(list(1, 0), list(0, 1)))) }, .mge)), "ERR ValueError: matrix must be a 4x4 matrix")
  expect_identical(.mgs(evalq({ equals(p, x1) }, .mge)), "False")
  try(utils::capture.output(evalq({ p_4d <- Point(0, 0, 0, 1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p_4d3d <- Point(0, 0, 1, 0) }, .mge)), silent = TRUE)
})

