test_that("point: test_arguments matches SymPy", {
  try(utils::capture.output(evalq({ "Functions accepting `Point` objects in `geometry`\n    should also accept tuples and lists and\n    automatically convert them to points." }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ singles2d <- list(list(1, 2), list(1, 2), Point(1, 2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ singles2d2 <- list(list(1, 3), list(1, 3), Point(1, 3)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ doubles2d <- cartes(singles2d, singles2d2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2d <- Point2D(1, 2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ singles3d <- list(list(1, 2, 3), list(1, 2, 3), Point(1, 2, 3)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ doubles3d <- subsets(singles3d, 2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p3d <- Point3D(1, 2, 3) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ singles4d <- list(list(1, 2, 3, 4), list(1, 2, 3, 4), Point(1, 2, 3, 4)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ doubles4d <- subsets(singles4d, 2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p4d <- Point(1, 2, 3, 4) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ test_single <- list("distance", "is_scalar_multiple", "taxicab_distance", "midpoint", "intersection", "dot", "equals", "__add__", "__sub__") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ test_double <- list("is_concyclic", "is_collinear") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ test_double <- list("is_collinear") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ test_double <- list("is_collinear") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ x <- Symbol("x") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ a <- Point(0, 1) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ a + list(0.1, x) }, .mge)), "Point2D(0.1, x + 1)")
  try(utils::capture.output(evalq({ a <- Point(0, 1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ a <- Point(0, 1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ u <- Point(0.1, 0.2, evaluate = FALSE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ u4 <- Point(u, dim = 4, on_morph = "ignore") }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ sym_args(u4) }, .mge)), "[0.100000000000000, 0.200000000000000, 0, 0]")
  expect_identical(.mgs(evalq({ Point(dim = 3, on_morph = "error") }, .mge)), "Point3D(0, 0, 0)")
  expect_identical(.mgs(evalq({ Point(1, 1, dim = 3, on_morph = "error") }, .mge)), "ERR ValueError: Dimension of (1, 1) needs to be changed from 2 to 3.")
  expect_identical(.mgs(evalq({ Point(1, 1, dim = 3, on_morph = "unknown") }, .mge)), "ERR ValueError: \\non_morph value should be 'error', 'warn' or 'ignore'.")
})

