test_that("point: test_direction_cosine matches SymPy", {
  try(utils::capture.output(evalq({ p1 <- Point3D(0, 0, 0) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2 <- Point3D(1, 1, 1) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ direction_cosine(p1, Point3D(1, 0, 0)) }, .mge)), "[1, 0, 0]")
  expect_identical(.mgs(evalq({ direction_cosine(p1, Point3D(0, 1, 0)) }, .mge)), "[0, 1, 0]")
  expect_identical(.mgs(evalq({ direction_cosine(p1, Point3D(0, 0, sym_pi)) }, .mge)), "[0, 0, 1]")
  expect_identical(.mgs(evalq({ direction_cosine(p1, Point3D(5, 0, 0)) }, .mge)), "[1, 0, 0]")
  expect_identical(.mgs(evalq({ direction_cosine(p1, Point3D(0, sqrt(S(3)), 0)) }, .mge)), "[0, 1, 0]")
  expect_identical(.mgs(evalq({ direction_cosine(p1, Point3D(0, 0, 5)) }, .mge)), "[0, 0, 1]")
