  expect_identical(.mgs(evalq({ direction_cosine(p1, Point3D(1, 1, 1)) }, .mge)), "[sqrt(3)/3, sqrt(3)/3, sqrt(3)/3]")
  expect_identical(.mgs(evalq({ direction_cosine(p1, Point3D(-12, 0, -15)) }, .mge)), "[-4*sqrt(41)/41, 0, -5*sqrt(41)/41]")
  expect_identical(.mgs(evalq({ direction_cosine(p2, Point3D(0, 0, 0)) }, .mge)), "[-sqrt(3)/3, -sqrt(3)/3, -sqrt(3)/3]")
  expect_identical(.mgs(evalq({ direction_cosine(p2, Point3D(1, 1, 12)) }, .mge)), "[0, 0, 1]")
  expect_identical(.mgs(evalq({ direction_cosine(p2, Point3D(12, 1, 12)) }, .mge)), "[sqrt(2)/2, 0, sqrt(2)/2]")
})

