test_that("line: test_object_from_equation matches SymPy", {
  expect_identical(.mgs(evalq({ Line(((3 * x) + y) + 18) }, .mge)), "Line2D(Point2D(0, -18), Point2D(1, -21))")
  expect_identical(.mgs(evalq({ Line(((3 * x) + (5 * y)) + 1) }, .mge)), "Line2D(Point2D(0, -1/5), Point2D(1, -4/5))")
  expect_identical(.mgs(evalq({ Line(((3 * a) + b) + 18, x = "a", y = "b") }, .mge)), "Line2D(Point2D(0, -18), Point2D(1, -21))")
  expect_identical(.mgs(evalq({ Line((3 * x) + y) }, .mge)), "Line2D(Point2D(0, 0), Point2D(1, -3))")
  expect_identical(.mgs(evalq({ Line(x + y) }, .mge)), "Line2D(Point2D(0, 0), Point2D(1, -1))")
  expect_identical(.mgs(evalq({ Line(Eq((3 * a) + b, -18), x = "a", y = b) }, .mge)), "Line2D(Point2D(0, -18), Point2D(1, -21))")
  expect_identical(.mgs(evalq({ Line(x - 1) }, .mge)), "Line2D(Point2D(1, 0), Point2D(1, 1))")
  expect_identical(.mgs(evalq({ Line((2 * x) - 2, y = x) }, .mge)), "Line2D(Point2D(0, 1), Point2D(1, 1))")
  expect_identical(.mgs(evalq({ Line(y) }, .mge)), "Line2D(Point2D(0, 0), Point2D(1, 0))")
  expect_identical(.mgs(evalq({ Line(2 * y, x = y) }, .mge)), "Line2D(Point2D(0, 0), Point2D(0, 1))")
  expect_identical(.mgs(evalq({ Line(y, x = y) }, .mge)), "Line2D(Point2D(0, 0), Point2D(0, 1))")
  expect_identical(.mgs(evalq({ Line(x / y) }, .mge)), "ERR NonlinearError: nonlinear term: 1/y")
  expect_identical(.mgs(evalq({ Line(a / b, x = "a", y = "b") }, .mge)), "ERR NonlinearError: nonlinear term: 1/b")
  expect_identical(.mgs(evalq({ Line(y / x) }, .mge)), "ERR NonlinearError: nonlinear term: 1/x")
  expect_identical(.mgs(evalq({ Line(b / a, x = "a", y = "b") }, .mge)), "ERR NonlinearError: nonlinear term: 1/a")
})

test_that("line: test_angle_between matches SymPy", {
