test_that("line: test_arbitrary_point matches SymPy", {
  try(utils::capture.output(evalq({ l1 <- Line3D(Point3D(0, 0, 0), Point3D(1, 1, 1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l2 <- Line(Point(x1, x1), Point(y1, y1)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ contains(l2, arbitrary_point(l2)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ arbitrary_point(Ray(list(1, 1), angle = sym_pi / 4)) }, .mge)), "Point2D(t + 1, t + 1)")
  expect_identical(.mgs(evalq({ arbitrary_point(Segment(list(1, 1), list(2, 3))) }, .mge)), "Point2D(t + 1, 2*t + 1)")
  expect_identical(.mgs(evalq({ perpendicular_segment(l1, arbitrary_point(l1)) }, .mge)), "Point3D(t, t, t)")
  expect_identical(.mgs(evalq({ arbitrary_point(Ray3D(list(1, 1, 1), direction_ratio = list(1, 2, 3))) }, .mge)), "Point3D(t + 1, 2*t + 1, 3*t + 1)")
  expect_identical(.mgs(evalq({ midpoint(Segment3D(Point3D(0, 0, 0), Point3D(1, 1, 1))) }, .mge)), "Point3D(1/2, 1/2, 1/2)")
  expect_identical(.mgs(evalq({ geo_length(Segment3D(Point3D(x1, x1, x1), Point3D(y1, y1, y1))) }, .mge)), "sqrt(3)*Abs(x1 - y1)")
  expect_identical(.mgs(evalq({ arbitrary_point(Segment3D(list(1, 1, 1), list(2, 3, 4))) }, .mge)), "Point3D(t + 1, 2*t + 1, 3*t + 1)")
  expect_identical(.mgs(evalq({ arbitrary_point(Line(list(x, 1), list(2, 3)), x) }, .mge)), "ERR ValueError: \\nSymbol x already appears in object and cannot be used as a parameter.")
})

test_that("line: test_are_concurrent_2d matches SymPy", {
