test_that("line: test_basic_properties_2d matches SymPy", {
  try(utils::capture.output(evalq({ p1 <- Point(0, 0) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2 <- Point(1, 1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p10 <- Point(2000, 2000) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p_r3 <- random_point(Ray(p1, p2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p_r4 <- random_point(Ray(p2, p1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l1 <- Line(p1, p2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l3 <- Line(Point(x1, x1), Point(x1, 1 + x1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l4 <- Line(p1, Point(1, 0)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ r1 <- Ray(p1, Point(0, 1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ r2 <- Ray(Point(0, 1), p1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ s1 <- Segment(p1, p10) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p_s1 <- random_point(s1) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ Line(list(1, 1), slope = 1) }, .mge)), "Line2D(Point2D(1, 1), Point2D(2, 2))")
  expect_identical(.mgs(evalq({ Line(list(1, 1), slope = oo) }, .mge)), "Line2D(Point2D(1, 1), Point2D(1, 2))")
  expect_identical(.mgs(evalq({ bounds(Line(list(1, 1), slope = oo)) }, .mge)), "[1, 1, 1, 2]")
  expect_identical(.mgs(evalq({ Line(list(1, 1), slope = -oo) }, .mge)), "Line2D(Point2D(1, 1), Point2D(1, 2))")
  expect_identical(.mgs(evalq({ geo_scale(Line(p1, p2), 2, 1) }, .mge)), "Line2D(Point2D(0, 0), Point2D(2, 1))")
  expect_identical(.mgs(evalq({ Line(p1, p2) }, .mge)), "Line2D(Point2D(0, 0), Point2D(1, 1))")
  expect_identical(.mgs(evalq({ Line(p1, p2) != Line(p2, p1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ l1 != Line(Point(x1, x1), Point(y1, y1)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ l1 != l3 }, .mge)), "True")
  expect_identical(.mgs(evalq({ Line(p1, p10) != Line(p10, p1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ Line(p1, p10) != p1 }, .mge)), "True")
  expect_identical(.mgs(evalq({ contains(l1, p1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ !contains(l3, p1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ contains(Line(p1, p10), s1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ contains(Ray(Point(0, 0), Point(0, 2)), Ray(Point(0, 0), Point(0, 1))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ contains(Ray(Point(0, 0), Point(0, 1)), Ray(Point(0, 0), Point(0, 2))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ xdirection(Ray(Point(0, 0), Point(0, 2))) }, .mge)), "0")
  expect_identical(.mgs(evalq({ xdirection(Ray(Point(0, 0), Point(1, 2))) }, .mge)), "oo")
  expect_identical(.mgs(evalq({ xdirection(Ray(Point(0, 0), Point(-1, 2))) }, .mge)), "-oo")
  expect_identical(.mgs(evalq({ ydirection(Ray(Point(0, 0), Point(2, 0))) }, .mge)), "0")
  expect_identical(.mgs(evalq({ ydirection(Ray(Point(0, 0), Point(2, 2))) }, .mge)), "oo")
  expect_identical(.mgs(evalq({ ydirection(Ray(Point(0, 0), Point(2, -2))) }, .mge)), "-oo")
  expect_identical(.mgs(evalq({ contains(s1, r1) }, .mge)), "False")
  expect_identical(.mgs(evalq({ contains(s1, Segment(p1, p2)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ Ray(Point(x1, x1), Point(x1, 1 + x1)) != Ray(p1, Point(-1, 5)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ midpoint(Segment(p1, p2)) }, .mge)), "Point2D(1/2, 1/2)")
  expect_identical(.mgs(evalq({ geo_length(Segment(p1, Point(-x1, x1))) }, .mge)), "sqrt(2)*Abs(x1)")
  expect_identical(.mgs(evalq({ slope(l1) }, .mge)), "1")
  expect_identical(.mgs(evalq({ slope(l3) }, .mge)), "oo")
  expect_identical(.mgs(evalq({ slope(l4) }, .mge)), "0")
  expect_identical(.mgs(evalq({ slope(Line(p1, Point(0, 1))) }, .mge)), "oo")
  expect_identical(.mgs(evalq({ geo_coefficients(l4) }, .mge)), "[0, 1, 0]")
  expect_identical(.mgs(evalq({ geo_coefficients(Line(list(-x, x), list((-x) + 1, x - 1))) }, .mge)), "[1, 1, 0]")
  expect_identical(.mgs(evalq({ geo_coefficients(Line(p1, Point(0, 1))) }, .mge)), "[1, 0, 0]")
  try(utils::capture.output(evalq({ r <- Ray(list(0, 0), angle = x) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ subs(r, x, (3 * sym_pi) / 4) }, .mge)), "Ray2D(Point2D(0, 0), Point2D(-1, 1))")
  expect_identical(.mgs(evalq({ subs(r, x, (5 * sym_pi) / 4) }, .mge)), "Ray2D(Point2D(0, 0), Point2D(-1, -1))")
  expect_identical(.mgs(evalq({ subs(r, x, (-sym_pi) / 4) }, .mge)), "Ray2D(Point2D(0, 0), Point2D(1, -1))")
  expect_identical(.mgs(evalq({ subs(r, x, sym_pi / 2) }, .mge)), "Ray2D(Point2D(0, 0), Point2D(0, 1))")
  expect_identical(.mgs(evalq({ subs(r, x, (-sym_pi) / 2) }, .mge)), "Ray2D(Point2D(0, 0), Point2D(0, -1))")
  expect_identical(.mgs(evalq({ (point_x(p_r3) >= point_x(p1)) && (point_y(p_r3) >= point_y(p1)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ (point_x(p_r4) <= point_x(p2)) && (point_y(p_r4) <= point_y(p2)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ plot_interval(s1) }, .mge)), "[t, 0, 1]")
  expect_identical(.mgs(evalq({ plot_interval(Line(p1, p10)) }, .mge)), "[t, -5, 5]")
  expect_identical(.mgs(evalq({ plot_interval(Ray(list(0, 0), angle = sym_pi / 4)) }, .mge)), "[t, 0, 10]")
})

