  expect_identical(.mgs(evalq({ contains(r, Ray(list(2, 2), list(3, 3))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ contains(r, Ray(list(2, 2), list(3, 5))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ contains(r1, Segment3D(p1, Point3D(0, 0, -10))) }, .mge)), "True")
