  expect_identical(.mgs(evalq({ distance(Line(p1, p2), Point(1, -1)) }, .mge)), "sqrt(2)")
  expect_identical(.mgs(evalq({ distance(Line(p1, p2), Point(2, 2)) }, .mge)), "0")
  expect_identical(.mgs(evalq({ distance(Line(p1, p2), list(-1, 1)) }, .mge)), "sqrt(2)")
  expect_identical(.mgs(evalq({ distance(Line(list(0, 0), list(0, 1)), p1) }, .mge)), "0")
  expect_identical(.mgs(evalq({ distance(Line(list(0, 0), list(0, 1)), p2) }, .mge)), "1")
  expect_identical(.mgs(evalq({ distance(Line(list(0, 0), list(1, 0)), p1) }, .mge)), "0")
  expect_identical(.mgs(evalq({ distance(Line(list(0, 0), list(1, 0)), p2) }, .mge)), "1")
  expect_identical(.mgs(evalq({ distance(r, Point(-1, -1)) }, .mge)), "sqrt(2)")
  expect_identical(.mgs(evalq({ distance(r, Point(1, 1)) }, .mge)), "0")
  expect_identical(.mgs(evalq({ distance(r, Point(-1, 1)) }, .mge)), "sqrt(2)")
  expect_identical(.mgs(evalq({ distance(Ray(list(1, 1), list(2, 2)), Point(1.5, 3)) }, .mge)), "3*sqrt(2)/4")
  expect_identical(.mgs(evalq({ distance(r, list(1, 1)) }, .mge)), "0")
})

