test_that("line: test_equals matches SymPy", {
  try(utils::capture.output(evalq({ p1 <- Point(0, 0) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2 <- Point(1, 1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l1 <- Line(p1, p2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l2 <- Line(list(0, 5), slope = m) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l3 <- Line(Point(x1, x1), Point(x1, 1 + x1)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ equals(perpendicular_line(l1, sym_args(p1)), Line(Point(0, 0), Point(1, -1))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ equals(perpendicular_line(l1, p1), Line(Point(0, 0), Point(1, -1))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ equals(parallel_line(Line(Point(x1, x1), Point(y1, y1)), Point(-x1, x1)), Line(Point(-x1, x1), Point(-y1, (2 * x1) - y1))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ equals(parallel_line(l3, sym_args(p1)), Line(Point(0, 0), Point(0, -1))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ equals(parallel_line(l3, p1), Line(Point(0, 0), Point(0, -1))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ equals(distance(l2, Point(2, 3)) - ((2 * Abs(m + 1)) / sqrt((m^2) + 1)), 0) }, .mge)), "True")
  expect_identical(.mgs(evalq({ equals(Line3D(p1, Point3D(0, 1, 0)), Point(1.0, 1.0)) }, .mge)), "False")
  expect_identical(.mgs(evalq({ equals(Line3D(Point3D(0, 0, 0), Point3D(1, 0, 0)), Line3D(Point3D(-5, 0, 0), Point3D(-1, 0, 0))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ equals(Line3D(Point3D(0, 0, 0), Point3D(1, 0, 0)), Line3D(p1, Point3D(0, 1, 0))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ equals(Ray3D(p1, Point3D(0, 0, -1)), Point(1.0, 1.0)) }, .mge)), "False")
  expect_identical(.mgs(evalq({ equals(Ray3D(p1, Point3D(0, 0, -1)), Ray3D(p1, Point3D(0, 0, -1))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ equals(perpendicular_line(Line3D(list(0, 0), list(t, t)), Point(0, 1, 0)), Line3D(Point3D(0, 1, 0), Point3D(S_Half, S_Half, 0))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ equals(perpendicular_segment(Line3D(list(0, 0), list(t, t)), Point(0, 1, 0)), Segment3D(list(0, 1), list(S_Half, S_Half))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ equals(Line3D(p1, Point3D(0, 1, 0)), Point(1.0, 1.0)) }, .mge)), "False")
})

test_that("line: test_equation matches SymPy", {
  try(utils::capture.output(evalq({ p1 <- Point(0, 0) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2 <- Point(1, 1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l1 <- Line(p1, p2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l3 <- Line(Point(x1, x1), Point(x1, 1 + x1)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ .bat_in(simplify(equation(l1)), list(x - y, y - x)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ .bat_in(simplify(equation(l3)), list(x - x1, x1 - x)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ .bat_in(simplify(equation(l1)), list(x - y, y - x)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ .bat_in(simplify(equation(l3)), list(x - x1, x1 - x)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ equation(Line(p1, Point(1, 0)), x = x, y = y) }, .mge)), "y")
  expect_identical(.mgs(evalq({ equation(Line(p1, Point(0, 1))) }, .mge)), "x")
  expect_identical(.mgs(evalq({ equation(Line(Point(2, 0), Point(2, 1))) }, .mge)), "x - 2")
  expect_identical(.mgs(evalq({ equation(Line(p2, Point(2, 1))) }, .mge)), "y - 1")
  expect_identical(.mgs(evalq({ equation(Line3D(Point(x1, x1, x1), Point(y1, y1, y1))) }, .mge)), "(-x + y, -x + z)")
  expect_identical(.mgs(evalq({ equation(Line3D(Point(1, 2, 3), Point(2, 3, 4))) }, .mge)), "(-x + y - 1, -x + z - 2)")
  expect_identical(.mgs(evalq({ equation(Line3D(Point(1, 2, 3), Point(1, 3, 4))) }, .mge)), "(x - 1, -y + z - 1)")
  expect_identical(.mgs(evalq({ equation(Line3D(Point(1, 2, 3), Point(2, 2, 4))) }, .mge)), "(y - 2, -x + z - 2)")
  expect_identical(.mgs(evalq({ equation(Line3D(Point(1, 2, 3), Point(2, 3, 3))) }, .mge)), "(-x + y - 1, z - 3)")
  expect_identical(.mgs(evalq({ equation(Line3D(Point(1, 2, 3), Point(1, 2, 4))) }, .mge)), "(x - 1, y - 2)")
  expect_identical(.mgs(evalq({ equation(Line3D(Point(1, 2, 3), Point(1, 3, 3))) }, .mge)), "(x - 1, z - 3)")
  expect_identical(.mgs(evalq({ equation(Line3D(Point(1, 2, 3), Point(2, 2, 3))) }, .mge)), "(y - 2, z - 3)")
})

test_that("line: test_intersection_2d matches SymPy", {
  try(utils::capture.output(evalq({ p1 <- Point(0, 0) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2 <- Point(1, 1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p3 <- Point(x1, x1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p4 <- Point(y1, y1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l1 <- Line(p1, p2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l3 <- Line(Point(0, 0), Point(3, 4)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ r1 <- Ray(Point(1, 1), Point(2, 2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ r2 <- Ray(Point(0, 0), Point(3, 4)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ r4 <- Ray(p1, p2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ r6 <- Ray(Point(0, 1), Point(1, 2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ r7 <- Ray(Point(0.5, 0.5), Point(1, 1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ s1 <- Segment(p1, p2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ s2 <- Segment(Point(0.25, 0.25), Point(0.5, 0.5)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ s3 <- Segment(Point(0, 0), Point(3, 4)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ intersection(l1, p1) }, .mge)), "[Point2D(0, 0)]")
  expect_identical(.mgs(evalq({ intersection(l1, Point(x1, 1 + x1)) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ .bat_in(intersection(l1, Line(p3, p4)), list(list(l1), list(Line(p3, p4)))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ intersection(l1, parallel_line(l1, Point(x1, 1 + x1))) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ intersection(l3, l3) }, .mge)), "[Line2D(Point2D(0, 0), Point2D(3, 4))]")
  expect_identical(.mgs(evalq({ intersection(l3, r2) }, .mge)), "[Ray2D(Point2D(0, 0), Point2D(3, 4))]")
  expect_identical(.mgs(evalq({ intersection(l3, s3) }, .mge)), "[Segment2D(Point2D(0, 0), Point2D(3, 4))]")
  expect_identical(.mgs(evalq({ intersection(s3, l3) }, .mge)), "[Segment2D(Point2D(0, 0), Point2D(3, 4))]")
  expect_identical(.mgs(evalq({ intersection(Segment(Point(-10, 10), Point(10, 10)), Segment(Point(-5, -5), Point(-5, 5))) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ intersection(r2, l3) }, .mge)), "[Ray2D(Point2D(0, 0), Point2D(3, 4))]")
  expect_identical(.mgs(evalq({ intersection(r1, Ray(Point(2, 2), Point(0, 0))) }, .mge)), "[Segment2D(Point2D(1, 1), Point2D(2, 2))]")
  expect_identical(.mgs(evalq({ intersection(r1, Ray(Point(1, 1), Point(-1, -1))) }, .mge)), "[Point2D(1, 1)]")
  expect_identical(.mgs(evalq({ intersection(r1, Segment(Point(0, 0), Point(2, 2))) }, .mge)), "[Segment2D(Point2D(1, 1), Point2D(2, 2))]")
  expect_identical(.mgs(evalq({ intersection(r4, s2) }, .mge)), "[Segment2D(Point2D(1/4, 1/4), Point2D(1/2, 1/2))]")
  expect_identical(.mgs(evalq({ intersection(r4, Segment(Point(2, 3), Point(3, 4))) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ intersection(r4, Segment(Point(-1, -1), Point(0.5, 0.5))) }, .mge)), "[Segment2D(Point2D(0, 0), Point2D(1/2, 1/2))]")
  expect_identical(.mgs(evalq({ intersection(r4, Ray(p2, p1)) }, .mge)), "[Segment2D(Point2D(0, 0), Point2D(1, 1))]")
  expect_identical(.mgs(evalq({ intersection(Ray(p2, p1), r6) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ intersection(Ray3D(list(0, 0), list(3, 0)), Ray3D(list(1, 0), list(3, 0))) }, .mge)), "[Ray3D(Point3D(1, 0, 0), Point3D(3, 0, 0))]")
  expect_identical(.mgs(evalq({ intersection(Ray3D(list(1, 0), list(3, 0)), Ray3D(list(0, 0), list(3, 0))) }, .mge)), "[Ray3D(Point3D(1, 0, 0), Point3D(3, 0, 0))]")
  expect_identical(.mgs(evalq({ intersection(Ray(Point(0, 0), Point(0, 4)), Ray(Point(0, 1), Point(0, -1))) }, .mge)), "[Segment2D(Point2D(0, 0), Point2D(0, 1))]")
  expect_identical(.mgs(evalq({ intersection(Segment3D(list(0, 0), list(3, 0)), Segment3D(list(1, 0), list(2, 0))) }, .mge)), "[Segment3D(Point3D(1, 0, 0), Point3D(2, 0, 0))]")
  expect_identical(.mgs(evalq({ intersection(Segment3D(list(1, 0), list(2, 0)), Segment3D(list(0, 0), list(3, 0))) }, .mge)), "[Segment3D(Point3D(1, 0, 0), Point3D(2, 0, 0))]")
  expect_identical(.mgs(evalq({ intersection(Segment3D(list(0, 0), list(3, 0)), Segment3D(list(3, 0), list(4, 0))) }, .mge)), "[Point3D(3, 0, 0)]")
  expect_identical(.mgs(evalq({ intersection(Segment3D(list(0, 0), list(3, 0)), Segment3D(list(2, 0), list(5, 0))) }, .mge)), "[Segment3D(Point3D(2, 0, 0), Point3D(3, 0, 0))]")
  expect_identical(.mgs(evalq({ intersection(Segment3D(list(0, 0), list(3, 0)), Segment3D(list(-2, 0), list(1, 0))) }, .mge)), "[Segment3D(Point3D(0, 0, 0), Point3D(1, 0, 0))]")
  expect_identical(.mgs(evalq({ intersection(Segment3D(list(0, 0), list(3, 0)), Segment3D(list(-2, 0), list(0, 0))) }, .mge)), "[Point3D(0, 0, 0)]")
  expect_identical(.mgs(evalq({ intersection(s1, Segment(Point(1, 1), Point(2, 2))) }, .mge)), "[Point2D(1, 1)]")
  expect_identical(.mgs(evalq({ intersection(s1, Segment(Point(0.5, 0.5), Point(1.5, 1.5))) }, .mge)), "[Segment2D(Point2D(1/2, 1/2), Point2D(1, 1))]")
  expect_identical(.mgs(evalq({ intersection(s1, Segment(Point(4, 4), Point(5, 5))) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ intersection(s1, Segment(Point(-1, -1), p1)) }, .mge)), "[Point2D(0, 0)]")
  expect_identical(.mgs(evalq({ intersection(s1, Segment(Point(-1, -1), Point(0.5, 0.5))) }, .mge)), "[Segment2D(Point2D(0, 0), Point2D(1/2, 1/2))]")
  expect_identical(.mgs(evalq({ intersection(s1, Line(Point(1, 0), Point(2, 1))) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ intersection(s1, s2) }, .mge)), "[Segment2D(Point2D(1/4, 1/4), Point2D(1/2, 1/2))]")
  expect_identical(.mgs(evalq({ intersection(s2, s1) }, .mge)), "[Segment2D(Point2D(1/4, 1/4), Point2D(1/2, 1/2))]")
  expect_identical(.mgs(evalq({ intersection(Line(list(0, 0), list(1, 1)), Ray(list(1, 0), list(1, 2))) }, .mge)), "[Point2D(1, 1)]")
  expect_identical(.mgs(evalq({ intersection(Line(list(0, 0), list(1, 1)), Segment(list(1, 0), list(1, 2))) }, .mge)), "[Point2D(1, 1)]")
  expect_identical(.mgs(evalq({ intersection(Ray(list(0, 0), list(1, 1)), Ray(list(1, 0), list(1, 2))) }, .mge)), "[Point2D(1, 1)]")
  expect_identical(.mgs(evalq({ intersection(Ray(list(0, 0), list(1, 1)), Segment(list(1, 0), list(1, 2))) }, .mge)), "[Point2D(1, 1)]")
  expect_identical(.mgs(evalq({ contains(Ray(list(0, 0), list(10, 10)), Segment(list(1, 1), list(2, 2))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ contains(Line(list(0, 0), list(10, 10)), Segment(list(1, 1), list(2, 2))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ intersection(s1, Ray(list(1, 1), list(4, 4))) }, .mge)), "[Point2D(1, 1)]")
})

