  expect_identical(.mgs(evalq({ intersection(l1, parallel_line(l1, p1)) }, .mge)), "[Line3D(Point3D(0, 0, 0), Point3D(1, 1, 1))]")
  expect_identical(.mgs(evalq({ intersection(l2, r2) }, .mge)), "[Ray3D(Point3D(0, 0, 0), Point3D(3, 4, 0))]")
  expect_identical(.mgs(evalq({ intersection(l2, s1) }, .mge)), "[Segment3D(Point3D(0, 0, 0), Point3D(3, 4, 0))]")
  expect_identical(.mgs(evalq({ intersection(r2, l2) }, .mge)), "[Ray3D(Point3D(0, 0, 0), Point3D(3, 4, 0))]")
  expect_identical(.mgs(evalq({ intersection(r1, Ray3D(Point3D(1, 1, 1), Point3D(-1, -1, -1))) }, .mge)), "[Point3D(1, 1, 1)]")
  expect_identical(.mgs(evalq({ intersection(r1, Segment3D(Point3D(0, 0, 0), Point3D(2, 2, 2))) }, .mge)), "[Segment3D(Point3D(1, 1, 1), Point3D(2, 2, 2))]")
  expect_identical(.mgs(evalq({ intersection(Ray3D(Point3D(1, 0, 0), Point3D(-1, 0, 0)), Ray3D(Point3D(0, 1, 0), Point3D(0, -1, 0))) }, .mge)), "[Point3D(0, 0, 0)]")
  expect_identical(.mgs(evalq({ intersection(r1, Ray3D(Point3D(2, 2, 2), Point3D(0, 0, 0))) }, .mge)), "[Segment3D(Point3D(1, 1, 1), Point3D(2, 2, 2))]")
  expect_identical(.mgs(evalq({ intersection(s1, r2) }, .mge)), "[Segment3D(Point3D(0, 0, 0), Point3D(3, 4, 0))]")
  expect_identical(.mgs(evalq({ intersection(Line3D(Point3D(4, 0, 1), Point3D(0, 4, 1)), Line3D(Point3D(0, 0, 1), Point3D(4, 4, 1))) }, .mge)), "[Point3D(2, 2, 1)]")
  expect_identical(.mgs(evalq({ intersection(Line3D(list(0, 1, 2), list(0, 2, 3)), Line3D(list(0, 1, 2), list(0, 1, 1))) }, .mge)), "[Point3D(0, 1, 2)]")
  expect_identical(.mgs(evalq({ intersection(Line3D(list(0, 0), list(t, t)), Line3D(list(0, 1), list(t, t))) }, .mge)), "[Point3D(t, t, 0)]")
  expect_identical(.mgs(evalq({ intersection(Ray3D(Point3D(0, 0, 0), Point3D(0, 4, 0)), Ray3D(Point3D(0, 1, 1), Point3D(0, -1, 1))) }, .mge)), "[]")
})

test_that("line: test_is_parallel matches SymPy", {
  try(utils::capture.output(evalq({ p1 <- Point3D(0, 0, 0) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2 <- Point3D(1, 1, 1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p3 <- Point3D(x1, x1, x1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l2 <- Line(Point(x1, x1), Point(y1, y1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l2_1 <- Line(Point(x1, x1), Point(x1, 1 + x1)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_parallel(Line(Point(0, 0), Point(1, 1)), l2) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_parallel(l2, Line(Point(x1, x1), Point(x1, 1 + x1))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_parallel(l2, parallel_line(l2, Point(-x1, x1))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_parallel(l2_1, parallel_line(l2_1, Point(0, 0))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_parallel(Line3D(p1, p2), Line3D(p1, p2)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_parallel(Line3D(Point3D(4, 0, 1), Point3D(0, 4, 1)), Line3D(Point3D(0, 0, 1), Point3D(4, 4, 1))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ parallel_line(Line3D(p1, p2), p3) }, .mge)), "Line3D(Point3D(sqrt(3), sqrt(3), sqrt(3)), Point3D(1 + sqrt(3), 1 + sqrt(3), 1 + sqrt(3)))")
  expect_identical(.mgs(evalq({ parallel_line(Line3D(p1, p2), sym_args(p3)) }, .mge)), "Line3D(Point3D(sqrt(3), sqrt(3), sqrt(3)), Point3D(1 + sqrt(3), 1 + sqrt(3), 1 + sqrt(3)))")
  expect_identical(.mgs(evalq({ is_parallel(Line3D(Point3D(4, 0, 1), Point3D(0, 4, 1)), Line3D(Point3D(0, 0, 1), Point3D(4, 4, 1))) }, .mge)), "False")
})

