test_that("line: test_projection matches SymPy", {
  try(utils::capture.output(evalq({ p1 <- Point(0, 0) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2 <- Point3D(0, 0, 0) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p3 <- Point(-x1, x1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l1 <- Line(p1, Point(1, 1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l2 <- Line3D(Point3D(0, 0, 0), Point3D(1, 0, 0)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l3 <- Line3D(p2, Point3D(1, 1, 1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ r1 <- Ray(Point(1, 1), Point(2, 2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ s1 <- Segment(Point2D(0, 0), Point2D(0, 1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .untranslated <- TRUE }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ projection(Line(Point(x1, x1), Point(y1, y1)), Point(y1, y1)) }, .mge)), "Point2D(y1, y1)")
  expect_identical(.mgs(evalq({ projection(Line(Point(x1, x1), Point(x1, 1 + x1)), Point(1, 1)) }, .mge)), "Point2D(sqrt(3), 1)")
  expect_identical(.mgs(evalq({ projection(Segment(Point(-2, 2), Point(0, 4)), r1) }, .mge)), "Segment2D(Point2D(-1, 3), Point2D(0, 4))")
  expect_identical(.mgs(evalq({ projection(Segment(Point(0, 4), Point(-2, 2)), r1) }, .mge)), "Segment2D(Point2D(0, 4), Point2D(-1, 3))")
  expect_identical(.mgs(evalq({ projection(l1, p3) }, .mge)), "Point2D(0, 0)")
  expect_identical(.mgs(evalq({ projection(l1, Ray(p1, Point(-1, 5))) }, .mge)), "Ray2D(Point2D(0, 0), Point2D(2, 2))")
  expect_identical(.mgs(evalq({ projection(l1, Ray(p1, Point(-1, 1))) }, .mge)), "Point2D(0, 0)")
  expect_identical(.mgs(evalq({ projection(r1, Ray(Point(1, 1), Point(-1, -1))) }, .mge)), "Point2D(1, 1)")
  expect_identical(.mgs(evalq({ projection(r1, Ray(Point(0, 4), Point(-1, -5))) }, .mge)), "Segment2D(Point2D(1, 1), Point2D(2, 2))")
  expect_identical(.mgs(evalq({ projection(r1, Segment(Point(-1, 5), Point(-5, -10))) }, .mge)), "Segment2D(Point2D(1, 1), Point2D(2, 2))")
  expect_identical(.mgs(evalq({ projection(r1, Ray(Point(1, 1), Point(-1, -1))) }, .mge)), "Point2D(1, 1)")
  expect_identical(.mgs(evalq({ projection(r1, Ray(Point(0, 4), Point(-1, -5))) }, .mge)), "Segment2D(Point2D(1, 1), Point2D(2, 2))")
  expect_identical(.mgs(evalq({ projection(r1, Segment(Point(-1, 5), Point(-5, -10))) }, .mge)), "Segment2D(Point2D(1, 1), Point2D(2, 2))")
  expect_identical(.mgs(evalq({ projection(l3, Ray3D(p2, Point3D(-1, 5, 0))) }, .mge)), "Ray3D(Point3D(0, 0, 0), Point3D(4/3, 4/3, 4/3))")
  expect_identical(.mgs(evalq({ projection(l3, Ray3D(p2, Point3D(-1, 1, 1))) }, .mge)), "Ray3D(Point3D(0, 0, 0), Point3D(1/3, 1/3, 1/3))")
  expect_identical(.mgs(evalq({ projection(l2, Point3D(5, 5, 0)) }, .mge)), "Point3D(5, 0, 0)")
  expect_identical(.mgs(evalq({ equals(projection(l2, Line3D(Point3D(0, 1, 0), Point3D(1, 1, 0))), l2) }, .mge)), "True")
})

