test_that("line: test_raises matches SymPy", {
  try(utils::capture.output(evalq({ d <- Symbol("a", real = TRUE); e <- Symbol("b", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ s <- Segment(list(d, 0), list(e, 0)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ Line(list(1, 1), 1) }, .mge)), "ERR TypeError: \\nExpecting sequence of coordinates, not `int`")
  expect_identical(.mgs(evalq({ Line(Point(0, 0), Point(0, 0)) }, .mge)), "ERR ValueError: Line2D.__new__ requires two unique Points.")
  expect_identical(.mgs(evalq({ contains(s, Point(2 * d, 0)) }, .mge)), "ERR Undecidable: Cannot determine if Point2D(2*a, 0) is in Segment2D(Point2D(a, 0), Point2D(b, 0))")
  expect_identical(.mgs(evalq({ Ray3D(Point(1.0, 1.0)) }, .mge)), "ERR ValueError: \\nA 2nd Point or keyword \"direction_ratio\" must be used.")
  expect_identical(.mgs(evalq({ Line3D(Point3D(0, 0, 0), Point3D(0, 0, 0)) }, .mge)), "ERR ValueError: Line3D.__new__ requires two unique Points.")
  expect_identical(.mgs(evalq({ Line3D(list(1, 1), 1) }, .mge)), "ERR TypeError: \\nExpecting sequence of coordinates, not `int`")
  expect_identical(.mgs(evalq({ Line3D(Point3D(0, 0, 0)) }, .mge)), "ERR ValueError: A 2nd Point or keyword \"direction_ratio\" must be used.")
  expect_identical(.mgs(evalq({ Ray(list(1, 1), 1) }, .mge)), "ERR TypeError: \\nExpecting sequence of coordinates, not `int`")
  expect_identical(.mgs(evalq({ projection(Line(Point(0, 0), Point(1, 0)), Circle(Point(0, 0), 1)) }, .mge)), "ERR GeometryError: Do not know how to project Circle(Point2D(0, 0), 1) onto Line2D(Point2D(0, 0), Point2D(1, 0))")
})

test_that("line: test_ray_generation matches SymPy", {
