test_that("ellipse: test_object_from_equation matches SymPy", {
  expect_identical(.mgs(evalq({ Circle(((((x^2) + (y^2)) + (3 * x)) + (4 * y)) - 8) }, .mge)), "Circle(Point2D(-3/2, -2), sqrt(57)/2)")
  expect_identical(.mgs(evalq({ Circle(((((x^2) + (y^2)) + (6 * x)) + (8 * y)) + 25) }, .mge)), "Point2D(-3, -4)")
  expect_identical(.mgs(evalq({ Circle(((((a^2) + (b^2)) + (6 * a)) + (8 * b)) + 25, x = "a", y = "b") }, .mge)), "Point2D(-3, -4)")
  expect_identical(.mgs(evalq({ Circle(((x^2) + (y^2)) - 25) }, .mge)), "Circle(Point2D(0, 0), 5)")
  expect_identical(.mgs(evalq({ Circle((x^2) + (y^2)) }, .mge)), "Point2D(0, 0)")
  expect_identical(.mgs(evalq({ Circle((a^2) + (b^2), x = "a", y = "b") }, .mge)), "Point2D(0, 0)")
  expect_identical(.mgs(evalq({ Circle((((x^2) + (y^2)) + (6 * x)) + 8) }, .mge)), "Circle(Point2D(-3, 0), 1)")
  expect_identical(.mgs(evalq({ Circle((((x^2) + (y^2)) + (6 * y)) + 8) }, .mge)), "Circle(Point2D(0, -3), 1)")
  expect_identical(.mgs(evalq({ Circle((((x - 1)^2) + (y^2)) - 9) }, .mge)), "Circle(Point2D(1, 0), 3)")
  expect_identical(.mgs(evalq({ Circle(((((6 * (x^2)) + (6 * (y^2))) + (6 * x)) + (8 * y)) - 25) }, .mge)), "Circle(Point2D(-1/2, -2/3), 5*sqrt(7)/6)")
  expect_identical(.mgs(evalq({ Circle(Eq((a^2) + (b^2), 25), x = "a", y = b) }, .mge)), "Circle(Point2D(0, 0), 5)")
  expect_identical(.mgs(evalq({ Circle(((((x^2) + (y^2)) + (3 * x)) + (4 * y)) + 26) }, .mge)), "ERR GeometryError: Circle with imaginary radius is not permitted")
  expect_identical(.mgs(evalq({ Circle(((x^2) + (y^2)) + 25) }, .mge)), "ERR GeometryError: Circle with imaginary radius is not permitted")
  expect_identical(.mgs(evalq({ Circle(((a^2) + (b^2)) + 25, x = "a", y = "b") }, .mge)), "ERR GeometryError: Circle with imaginary radius is not permitted")
  expect_identical(.mgs(evalq({ Circle(((x^2) + (6 * y)) + 8) }, .mge)), "ERR GeometryError: The given equation is not that of a circle.")
  expect_identical(.mgs(evalq({ Circle(((((6 * (x^2)) + (4 * (y^2))) + (6 * x)) + (8 * y)) + 25) }, .mge)), "ERR GeometryError: The given equation is not that of a circle.")
  expect_identical(.mgs(evalq({ Circle(((((a^2) + (b^2)) + (3 * a)) + (4 * b)) - 8) }, .mge)), "ERR ValueError: could not find x")
  try(utils::capture.output(evalq({ x <- Symbol("x", real = TRUE); y <- Symbol("y", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ eq <- ((((a * (x^2)) + (a * (y^2))) + (c * x)) + (d * y)) + e }, .mge)), silent = TRUE)
})

test_that("ellipse: test_construction matches SymPy", {
  try(utils::capture.output(evalq({ e1 <- Ellipse(hradius = 2, vradius = 1, eccentricity = NULL) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ eccentricity(e1) }, .mge)), "sqrt(3)/2")
  try(utils::capture.output(evalq({ e2 <- Ellipse(hradius = 2, vradius = NULL, eccentricity = sqrt(S(3)) / 2) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ e2$vradius }, .mge)), "1")
  try(utils::capture.output(evalq({ e3 <- Ellipse(hradius = NULL, vradius = 1, eccentricity = sqrt(S(3)) / 2) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ e3$hradius }, .mge)), "2")
  try(utils::capture.output(evalq({ e4 <- Ellipse(Point(0, 0), hradius = 1, eccentricity = 0) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ e4$vradius }, .mge)), "1")
  expect_identical(.mgs(evalq({ Ellipse(Point(3, 1), hradius = 3, eccentricity = S(3) / 2) }, .mge)), "ERR GeometryError: Invalid value encountered when computing hradius / vradius.")
  expect_identical(.mgs(evalq({ Ellipse(Point(3, 1), hradius = 3, eccentricity = sec(5)) }, .mge)), "ERR GeometryError: Invalid value encountered when computing hradius / vradius.")
  expect_identical(.mgs(evalq({ Ellipse(Point(3, 1), hradius = 3, eccentricity = sym_pi - S(2)) }, .mge)), "ERR GeometryError: Invalid value encountered when computing hradius / vradius.")
  expect_identical(.mgs(evalq({ geo_length(Ellipse(NULL, 1, NULL, 1)) }, .mge)), "2")
  expect_identical(.mgs(evalq({ Ellipse(NULL, NULL, 1, eccentricity = 1) }, .mge)), "ERR GeometryError: Invalid value encountered when computing hradius / vradius.")
  expect_identical(.mgs(evalq({ Ellipse(Point(3, 1), hradius = 3, eccentricity = -3) }, .mge)), "ERR GeometryError: Eccentricity of ellipse/circle should lie between [0, 1)")
  expect_identical(.mgs(evalq({ Ellipse(Point(3, 1), hradius = 3, eccentricity = -0.5) }, .mge)), "ERR GeometryError: Eccentricity of ellipse/circle should lie between [0, 1)")
})

