test_that("ellipse: test_transform matches SymPy", {
  try(utils::capture.output(evalq({ c <- Circle(list(1, 1), 2) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ geo_scale(c, -1) }, .mge)), "Circle(Point2D(-1, 1), 2)")
  expect_identical(.mgs(evalq({ geo_scale(c, y = -1) }, .mge)), "Circle(Point2D(1, -1), 2)")
  expect_identical(.mgs(evalq({ geo_scale(c, 2) }, .mge)), "Ellipse(Point2D(2, 1), 4, 2)")
  expect_identical(.mgs(evalq({ geo_scale(Ellipse(list(0, 0), 2, 3), 2, 3, list(4, 5)) }, .mge)), "Ellipse(Point2D(-4, -10), 4, 9)")
  expect_identical(.mgs(evalq({ geo_scale(Circle(list(0, 0), 2), 2, 3, list(4, 5)) }, .mge)), "Ellipse(Point2D(-4, -10), 4, 6)")
  expect_identical(.mgs(evalq({ geo_scale(Ellipse(list(0, 0), 2, 3), 3, 3, list(4, 5)) }, .mge)), "Ellipse(Point2D(-8, -10), 6, 9)")
  expect_identical(.mgs(evalq({ geo_scale(Circle(list(0, 0), 2), 3, 3, list(4, 5)) }, .mge)), "Circle(Point2D(-8, -10), 6)")
  expect_identical(.mgs(evalq({ geo_scale(Circle(Point(-8, -10), 6), Rational(1, 3), Rational(1, 3), list(4, 5)) }, .mge)), "Circle(Point2D(0, 0), 2)")
  expect_identical(.mgs(evalq({ translate(Circle(list(0, 0), 2), 4, 5) }, .mge)), "Circle(Point2D(4, 5), 2)")
  expect_identical(.mgs(evalq({ geo_scale(Circle(list(0, 0), 2), 3, 3) }, .mge)), "Circle(Point2D(0, 0), 6)")
})

