test_that("ellipse: test_is_tangent matches SymPy", {
  try(utils::capture.output(evalq({ e1 <- Ellipse(Point(0, 0), 3, 5) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ c1 <- Circle(Point(2, -2), 7) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_tangent(e1, Point(0, 0)) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Point(3, 0)) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, e1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_tangent(e1, Ellipse(list(0, 0), 1, 2)) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Ellipse(list(0, 0), 3, 2)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_tangent(c1, Ellipse(list(2, -2), 7, 1)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_tangent(c1, Circle(list(11, -2), 2)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_tangent(c1, Circle(list(7, -2), 2)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_tangent(c1, Ray(list(-5, -2), list(-15, -20))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(c1, Ray(list(-3, -2), list(-15, -20))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(c1, Ray(list(-3, -22), list(15, 20))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(c1, Ray(list(9, 20), list(9, -20))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_tangent(c1, Ray(list(2, 5), list(9, 5))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_tangent(c1, Segment(list(2, 5), list(9, 5))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_tangent(e1, Segment(list(2, 2), list(-7, 7))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Segment(list(0, 0), list(1, 2))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(c1, Segment(list(0, 0), list(-5, -2))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Segment(list(3, 0), list(12, 12))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Segment(list(12, 12), list(3, 0))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Segment(list(-3, 0), list(3, 0))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Segment(list(-3, 5), list(3, 5))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_tangent(e1, Line(list(10, 0), list(10, 10))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Line(list(0, 0), list(1, 1))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Line(list(-3, 0), list(-2.99, -0.001))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Line(list(-3, 0), list(-3, 1))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_tangent(e1, Polygon(list(0, 0), list(5, 5), list(5, -5))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Polygon(list(-100, -50), list(-40, -334), list(-70, -52))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Polygon(list(-3, 0), list(3, 0), list(0, 1))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Polygon(list(-3, 0), list(3, 0), list(0, 5))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Polygon(list(-3, 0), list(0, -5), list(3, 0), list(0, 5))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Polygon(list(-3, -5), list(-3, 5), list(3, 5), list(3, -5))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_tangent(c1, Polygon(list(-3, -5), list(-3, 5), list(3, 5), list(3, -5))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Polygon(list(0, 0), list(3, 0), list(7, 7), list(0, 5))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Polygon(list(3, 12), list(3, -12), list(6, 5))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Polygon(list(3, 12), list(3, -12), list(0, -5), list(0, 5))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Polygon(list(3, 0), list(5, 7), list(6, -5))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(c1, Segment(list(0, 0), list(-5, -2))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Segment(list(-3, 0), list(3, 0))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Segment(list(-3, 5), list(3, 5))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_tangent(e1, Polygon(list(0, 0), list(5, 5), list(5, -5))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Polygon(list(-100, -50), list(-40, -334), list(-70, -52))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Polygon(list(-3, -5), list(-3, 5), list(3, 5), list(3, -5))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_tangent(c1, Polygon(list(-3, -5), list(-3, 5), list(3, 5), list(3, -5))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Polygon(list(3, 12), list(3, -12), list(0, -5), list(0, 5))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Polygon(list(3, 0), list(5, 7), list(6, -5))) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_tangent(e1, Point(0, 0, 0)) }, .mge)), "ERR TypeError: Entity must be two dimensional, not three dimensional")
  expect_identical(.mgs(evalq({ is_tangent(e1, Rational(5)) }, .mge)), "ERR TypeError: Is_tangent not handled for Integer")
})

