test_that("ellipse: test_section_modulus_and_polar_second_moment_of_area matches SymPy", {
  try(utils::capture.output(evalq({ d <- Symbol("d", positive = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ c <- Circle(list(3, 7), 8) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ polar_second_moment_of_area(c) }, .mge)), "2048*pi")
  expect_identical(.mgs(evalq({ section_modulus(c) }, .mge)), "[128*pi, 128*pi]")
  try(utils::capture.output(evalq({ c <- Circle(list(2, 9), d / 2) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ polar_second_moment_of_area(c) }, .mge)), "pi*d^4/32")
  expect_identical(.mgs(evalq({ section_modulus(c) }, .mge)), "[pi*d^3/32, pi*d^3/32]")
  try(utils::capture.output(evalq({ a <- Symbol("a", positive = TRUE); b <- Symbol("b", positive = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ e <- Ellipse(list(4, 6), a, b) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ section_modulus(e) }, .mge)), "[pi*a*b^2/4, pi*a^2*b/4]")
  expect_identical(.mgs(evalq({ polar_second_moment_of_area(e) }, .mge)), "pi*a^3*b/4 + pi*a*b^3/4")
  try(utils::capture.output(evalq({ e <- geo_rotate(e, sym_pi / 2) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ section_modulus(e) }, .mge)), "[pi*a^2*b/4, pi*a*b^2/4]")
  expect_identical(.mgs(evalq({ polar_second_moment_of_area(e) }, .mge)), "pi*a^3*b/4 + pi*a*b^3/4")
  try(utils::capture.output(evalq({ e <- Ellipse(list(a, b), 2, 6) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ section_modulus(e) }, .mge)), "[18*pi, 6*pi]")
  expect_identical(.mgs(evalq({ polar_second_moment_of_area(e) }, .mge)), "120*pi")
  try(utils::capture.output(evalq({ e <- Ellipse(Point(0, 0), 2, 2) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ section_modulus(e) }, .mge)), "[2*pi, 2*pi]")
  expect_identical(.mgs(evalq({ section_modulus(e, Point(2, 2)) }, .mge)), "[2*pi, 2*pi]")
  expect_identical(.mgs(evalq({ section_modulus(e, list(2, 2)) }, .mge)), "[2*pi, 2*pi]")
})

