test_that("ellipse: test_evolute matches SymPy", {
  try(utils::capture.output(evalq({ x <- Symbol("x", real = TRUE); y <- Symbol("y", real = TRUE); h <- Symbol("h", real = TRUE); k <- Symbol("k", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ a <- Symbol("a"); b <- Symbol("b") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ e <- Ellipse(Point(h, k), a, b) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ t1 <- (e$hradius * (x - point_x(e$center)))^Rational(2, 3) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ t2 <- (e$vradius * (y - point_y(e$center)))^Rational(2, 3) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ sym_E <- (t1 + t2) - (((e$hradius^2) - (e$vradius^2))^Rational(2, 3)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ evolute(e) }, .mge)), "(a*(-h + x))^(2/3) + (b*(-k + y))^(2/3) - (a^2 - b^2)^(2/3)")
  try(utils::capture.output(evalq({ e <- Ellipse(Point(1, 1), 6, 3) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ t1 <- (6 * (x - 1))^Rational(2, 3) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ t2 <- (3 * (y - 1))^Rational(2, 3) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ sym_E <- (t1 + t2) - (27^Rational(2, 3)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ evolute(e) }, .mge)), "(6*x - 6)^(2/3) + (3*y - 3)^(2/3) - 9")
})

