  expect_identical(.mgs(evalq({ intersection(poly1, poly2) }, .mge)), "[Point2D(1/3, 0), Segment2D(Point2D(0, 1/5), Point2D(0, 0)), Segment2D(Point2D(1, 0), Point2D(0, 1))]")
  expect_identical(.mgs(evalq({ intersection(poly2, poly1) }, .mge)), "[Point2D(1/3, 0), Segment2D(Point2D(0, 0), Point2D(0, 1/5)), Segment2D(Point2D(1, 0), Point2D(0, 1))]")
  expect_identical(.mgs(evalq({ intersection(poly1, Point(0, 0)) }, .mge)), "[Point2D(0, 0)]")
  expect_identical(.mgs(evalq({ intersection(poly1, Point(-12, -43)) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ intersection(poly2, Line(list(-12, 0), list(12, 0))) }, .mge)), "[Point2D(-5, 0), Point2D(0, 0), Point2D(1/3, 0), Point2D(1, 0)]")
  expect_identical(.mgs(evalq({ intersection(poly2, Line(list(-12, 12), list(12, 12))) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ intersection(poly2, Ray(list(-3, 4), list(1, 0))) }, .mge)), "[Segment2D(Point2D(1, 0), Point2D(0, 1))]")
  expect_identical(.mgs(evalq({ intersection(poly2, Circle(list(0, -1), 1)) }, .mge)), "[Point2D(0, -2), Point2D(0, 0)]")
  expect_identical(.mgs(evalq({ intersection(poly1, poly1) }, .mge)), "[Segment2D(Point2D(0, 0), Point2D(1, 0)), Segment2D(Point2D(0, 1), Point2D(0, 0)), Segment2D(Point2D(1, 0), Point2D(0, 1))]")
  expect_identical(.mgs(evalq({ intersection(poly2, poly2) }, .mge)), "[Segment2D(Point2D(-5, 0), Point2D(0, -4)), Segment2D(Point2D(0, -4), Point2D(0, 1/5)), Segment2D(Point2D(0, 1/5), Point2D(1/2, -1/10)), Segment2D(Point2D(0, 1), Point2D(-5, 0)), Segment2D(Point2D(1/2, -1/10), Point2D(1, 0)), Segment2D(Point2D(1, 0), Point2D(0, 1))]")
  expect_identical(.mgs(evalq({ intersection(poly2, Triangle(Point(0, 1), Point(1, 0), Point(-1, 1))) }, .mge)), "[Point2D(-5/7, 6/7), Segment2D(Point2D(0, 1), Point2D(1, 0))]")
