test_that("polygon: test_second_moment_of_area matches SymPy", {
  try(utils::capture.output(evalq({ x <- Symbol("x"); y <- Symbol("y") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- list(list(0, 0), list(4, 0), list(0, 2)); p1 <- .tup[[1]]; p2 <- .tup[[2]]; p3 <- .tup[[3]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p <- list(0, 0) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ eq_y <- (1 - (x / 4)) * 2 }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ I_yy <- sym_integrate((x^2) * sym_integrate(1, list(y, 0, eq_y)), list(x, 0, 4)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ I_xx <- sym_integrate(1 * sym_integrate(y^2, list(y, 0, eq_y)), list(x, 0, 4)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ I_xy <- sym_integrate(x * sym_integrate(y, list(y, 0, eq_y)), list(x, 0, 4)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ triangle <- Polygon(p1, p2, p3) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ I_xx - second_moment_of_area(triangle, p)[[1]] }, .mge)), "0")
  expect_identical(.mgs(evalq({ I_yy - second_moment_of_area(triangle, p)[[2]] }, .mge)), "0")
  expect_identical(.mgs(evalq({ I_xy - second_moment_of_area(triangle, p)[[3]] }, .mge)), "0")
  try(utils::capture.output(evalq({ .tup <- list(list(0, 0), list(4, 0), list(4, 2), list(0, 2)); p1 <- .tup[[1]]; p2 <- .tup[[2]]; p3 <- .tup[[3]]; p4 <- .tup[[4]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ I_yy <- sym_integrate((x^2) * sym_integrate(1, list(y, 0, 2)), list(x, 0, 4)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ I_xx <- sym_integrate(1 * sym_integrate(y^2, list(y, 0, 2)), list(x, 0, 4)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ I_xy <- sym_integrate(x * sym_integrate(y, list(y, 0, 2)), list(x, 0, 4)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ rectangle <- Polygon(p1, p2, p3, p4) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ I_xx - second_moment_of_area(rectangle, p)[[1]] }, .mge)), "0")
  expect_identical(.mgs(evalq({ I_yy - second_moment_of_area(rectangle, p)[[2]] }, .mge)), "0")
  expect_identical(.mgs(evalq({ I_xy - second_moment_of_area(rectangle, p)[[3]] }, .mge)), "0")
  try(utils::capture.output(evalq({ r <- RegularPolygon(Point(0, 0), 5, 3) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ second_moment_of_area(r) }, .mge)), "[1875*sqrt(3)/32, 1875*sqrt(3)/32, 0]")
})

