test_that("polygon: test_section_modulus_and_polar_second_moment_of_area matches SymPy", {
  try(utils::capture.output(evalq({ a <- Symbol("a", positive = TRUE); b <- Symbol("b", positive = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ x <- Symbol("x"); y <- Symbol("y") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ rectangle <- Polygon(list(0, b), list(0, 0), list(a, 0), list(a, b)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ section_modulus(rectangle, Point(x, y)) }, .mge)), "[a*b^3/(12*(-b/2 + y)), a^3*b/(12*(-a/2 + x))]")
  expect_identical(.mgs(evalq({ polar_second_moment_of_area(rectangle) }, .mge)), "a^3*b/12 + a*b^3/12")
  try(utils::capture.output(evalq({ convex <- RegularPolygon(list(0, 0), 1, 6) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ section_modulus(convex) }, .mge)), "[5/8, 5*sqrt(3)/16]")
  expect_identical(.mgs(evalq({ polar_second_moment_of_area(convex) }, .mge)), "5*sqrt(3)/8")
  try(utils::capture.output(evalq({ concave <- Polygon(list(0, 0), list(1, 8), list(3, 4), list(4, 6), list(7, 1)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ section_modulus(concave) }, .mge)), "[-6371/429, -9778/519]")
  expect_identical(.mgs(evalq({ polar_second_moment_of_area(concave) }, .mge)), "-38669/252")
})

test_that("polygon: test_cut_section matches SymPy", {
  try(utils::capture.output(evalq({ p <- Polygon(list(-1, -1), list(1, Rational(5, 2)), list(2, 1), list(3, Rational(5, 2)), list(4, 2), list(5, 3), list(-1, 3)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l <- Line(list(0, 0), list(Rational(9, 2), 3)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p1 <- cut_section(p, l)[[1]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2 <- cut_section(p, l)[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ p1 }, .mge)), "Polygon(Point2D(-9/13, -6/13), Point2D(1, 5/2), Point2D(24/13, 16/13), Point2D(12/5, 8/5), Point2D(3, 5/2), Point2D(24/7, 16/7), Point2D(9/2, 3), Point2D(-1, 3), Point2D(-1, -2/3))")
  expect_identical(.mgs(evalq({ p2 }, .mge)), "Polygon(Point2D(-1, -1), Point2D(-9/13, -6/13), Point2D(24/13, 16/13), Point2D(2, 1), Point2D(12/5, 8/5), Point2D(24/7, 16/7), Point2D(4, 2), Point2D(5, 3), Point2D(9/2, 3), Point2D(-1, -2/3))")
  try(utils::capture.output(evalq({ p <- RegularPolygon(Point2D(0, 0), 6, 6) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ s <- cut_section(p, Line(list(0, 0), slope = 1)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ s[[1]] }, .mge)), "Polygon(Point2D(9 - 3*sqrt(3), 9 - 3*sqrt(3)), Point2D(3, 3*sqrt(3)), Point2D(-3, 3*sqrt(3)), Point2D(-6, 0), Point2D(-9 + 3*sqrt(3), -9 + 3*sqrt(3)))")
  expect_identical(.mgs(evalq({ s[[2]] }, .mge)), "Polygon(Point2D(6, 0), Point2D(9 - 3*sqrt(3), 9 - 3*sqrt(3)), Point2D(-9 + 3*sqrt(3), -9 + 3*sqrt(3)), Point2D(-3, -3*sqrt(3)), Point2D(3, -3*sqrt(3)))")
  try(utils::capture.output(evalq({ .tup <- list(20, 10); a <- .tup[[1]]; b <- .tup[[2]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- list(list(0, b), list(0, 0), list(a, 0), list(a, b)); t1 <- .tup[[1]]; t2 <- .tup[[2]]; t3 <- .tup[[3]]; t4 <- .tup[[4]] }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p <- Polygon(t1, t2, t3, t4) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .tup <- cut_section(p, Line(list(0, b), slope = 0)); p1 <- .tup[[1]]; p2 <- .tup[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ p1 }, .mge)), "None")
  expect_identical(.mgs(evalq({ p2 }, .mge)), "Polygon(Point2D(0, 10), Point2D(0, 0), Point2D(20, 0), Point2D(20, 10))")
  try(utils::capture.output(evalq({ .tup <- cut_section(p, Line(list(0, 0), slope = 0)); p3 <- .tup[[1]]; p4 <- .tup[[2]] }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ p3 }, .mge)), "Polygon(Point2D(0, 10), Point2D(0, 0), Point2D(20, 0), Point2D(20, 10))")
  expect_identical(.mgs(evalq({ p4 }, .mge)), "None")
  expect_identical(.mgs(evalq({ cut_section(p, Line(list(0, a), slope = 0)) }, .mge)), "ERR ValueError: This line does not intersect the polygon")
})

test_that("polygon: test_type_of_triangle matches SymPy", {
  try(utils::capture.output(evalq({ p1 <- Polygon(Point(0, 0), Point(5, 0), Point(2, 4)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_isosceles(p1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_scalene(p1) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_equilateral(p1) }, .mge)), "False")
  try(utils::capture.output(evalq({ p2 <- Polygon(Point(0, 0), Point(0, 2), Point(4, 0)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_isosceles(p2) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_scalene(p2) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_equilateral(p2) }, .mge)), "False")
  try(utils::capture.output(evalq({ p3 <- Polygon(Point(0, 0), Point(6, 0), Point(3, sqrt(S(27)))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ is_isosceles(p3) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_scalene(p3) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_equilateral(p3) }, .mge)), "True")
})

test_that("polygon: test_centroid_zero_area matches SymPy", {
