.mge <- .mgs_env()
test_that("plane: test_plane matches SymPy", {
  try(utils::capture.output(evalq({ x <- Symbol("x", real = TRUE); y <- Symbol("y", real = TRUE); z <- Symbol("z", real = TRUE); u <- Symbol("u", real = TRUE); v <- Symbol("v", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p1 <- Point3D(0, 0, 0) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2 <- Point3D(1, 1, 1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p3 <- Point3D(1, 2, 3) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ pl3 <- Plane(p1, p2, p3) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ pl4 <- Plane(p1, normal_vector = list(1, 1, 1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ pl4b <- Plane(p1, p2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ pl5 <- Plane(p3, normal_vector = list(1, 2, 3)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ pl6 <- Plane(Point3D(2, 3, 7), normal_vector = list(2, 2, 2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ pl7 <- Plane(Point3D(1, -5, -6), normal_vector = list(1, -2, 1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ pl8 <- Plane(p1, normal_vector = list(0, 0, 1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ pl9 <- Plane(p1, normal_vector = list(0, 12, 0)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ pl10 <- Plane(p1, normal_vector = list(-2, 0, 0)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ pl11 <- Plane(p2, normal_vector = list(0, 0, 1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l1 <- Line3D(Point3D(5, 0, 0), Point3D(1, -1, 1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l2 <- Line3D(Point3D(0, -2, 0), Point3D(3, 1, 1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l3 <- Line3D(Point3D(0, -1, 0), Point3D(5, -1, 9)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ Plane(p1, p1, p1) }, .mge)), "ERR ValueError: Enter three non-collinear points")
  expect_identical(.mgs(evalq({ Plane(p1, p2, p3) != Plane(p1, p3, p2) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_coplanar(Plane(p1, p2, p3), Plane(p1, p3, p2)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_coplanar(Plane(p1, p2, p3), p1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ is_coplanar(Plane(p1, p2, p3), Circle(p1, 1)) }, .mge)), "False")
  expect_identical(.mgs(evalq({ is_coplanar(Plane(p1, normal_vector = list(0, 0, 1)), Circle(p1, 1)) }, .mge)), "True")
  expect_identical(.mgs(evalq({ pl3 }, .mge)), "Plane(Point3D(0, 0, 0), (1, -2, 1))")
  expect_identical(.mgs(evalq({ pl3 != pl4 }, .mge)), "True")
  expect_identical(.mgs(evalq({ pl4 }, .mge)), "Plane(Point3D(0, 0, 0), (1, 1, 1))")
  expect_identical(.mgs(evalq({ pl5 }, .mge)), "Plane(Point3D(1, 2, 3), (1, 2, 3))")
  expect_identical(.mgs(evalq({ equation(pl5, x, y, z) }, .mge)), "x + 2*y + 3*z - 14")
  expect_identical(.mgs(evalq({ equation(pl3, x, y, z) }, .mge)), "x - 2*y + z")
  expect_identical(.mgs(evalq({ pl3$p1 }, .mge)), "Point3D(0, 0, 0)")
  expect_identical(.mgs(evalq({ pl4$p1 }, .mge)), "Point3D(0, 0, 0)")
  expect_identical(.mgs(evalq({ pl5$p1 }, .mge)), "Point3D(1, 2, 3)")
  expect_identical(.mgs(evalq({ normal_vector(pl4) }, .mge)), "(1, 1, 1)")
  expect_identical(.mgs(evalq({ normal_vector(pl5) }, .mge)), "(1, 2, 3)")
  expect_identical(.mgs(evalq({ contains(pl3, p1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ contains(pl4, p1) }, .mge)), "True")
  expect_identical(.mgs(evalq({ contains(pl5, p3) }, .mge)), "True")
  expect_identical(.mgs(evalq({ projection(pl3, Point(0, 0)) }, .mge)), "Point3D(0, 0, 0)")
  try(utils::capture.output(evalq({ p <- projection(pl3, Point3D(1, 1, 0)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ p }, .mge)), "Point3D(7/6, 2/3, 1/6)")
  expect_identical(.mgs(evalq({ contains(pl3, p) }, .mge)), "True")
