  expect_identical(.mgs(evalq({ l }, .mge)), "Line3D(Point3D(0, 0, 0), Point3D(7/6, 2/3, 1/6))")
  expect_identical(.mgs(evalq({ contains(pl3, l) }, .mge)), "True")
  try(utils::capture.output(evalq({ t <- Dummy() }, .mge)), silent = TRUE)
