  expect_identical(.mgs(evalq({ is_perpendicular(pl6, list(1, 1)) }, .mge)), "False")
  expect_identical(.mgs(evalq({ distance(pl6, arbitrary_point(pl6, u, v)) }, .mge)), "0")
  expect_identical(.mgs(evalq({ distance(pl7, arbitrary_point(pl7, u, v)) }, .mge)), "0")
  expect_identical(.mgs(evalq({ simplify(distance(pl6, arbitrary_point(pl6, t))) }, .mge)), "0")
