  expect_identical(.mgs(evalq({ equals(intersection(pl8, Plane(p1, normal_vector = list(11, 0, 1)))[[1]], Line3D(p1, direction_ratio = list(0, -11, 0))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ equals(intersection(pl8, Plane(p1, normal_vector = list(1, 0, 11)))[[1]], Line3D(p1, direction_ratio = list(0, 11, 0))) }, .mge)), "True")
  expect_identical(.mgs(evalq({ equals(intersection(pl8, Plane(p1, normal_vector = list(-1, -1, -11)))[[1]], Line3D(p1, direction_ratio = list(1, -1, 0))) }, .mge)), "True")
