  try(utils::capture.output(evalq({ l2 <- Line3D(Point3D(Rational(50000004459633, 5000000000000), Rational(-891926590718643, 1000000000000000), Rational(231800966893633, 100000000000000)), Point3D(Rational(50000004459633, 50000000000000), Rational(-222981647679771, 250000000000000), Rational(231800966893633, 100000000000000))) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2 <- Plane(Point3D(Rational(402775636372767, 100000000000000), Rational(-97224357654973, 100000000000000), Rational(216793600814789, 100000000000000)), list(-S("9.00000087501922"), -S("4.81170658872543e-13"), S("0.0"))) }, .mge)), silent = TRUE)
