test_that("plane: test_plane_distance_parallel_segment_ray matches SymPy", {
  try(utils::capture.output(evalq({ p <- Plane(list(0, 0, 0), normal_vector = list(0, 0, 1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ s1 <- Segment3D(list(0, 0, 1), list(1, 0, 1)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ r1 <- Ray3D(list(0, 0, 1), list(1, 0, 1)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ distance(p, s1) }, .mge)), "1")
  expect_identical(.mgs(evalq({ distance(p, r1) }, .mge)), "1")
  try(utils::capture.output(evalq({ r_away <- Ray3D(list(0, 0, 1), list(0, 0, 2)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ distance(p, r_away) }, .mge)), "1")
  try(utils::capture.output(evalq({ s_in <- Segment3D(list(0, 0, 0), list(2, 3, 0)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ r_in <- Ray3D(list(0, 0, 0), list(2, 3, 0)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ distance(p, s_in) }, .mge)), "0")
  expect_identical(.mgs(evalq({ distance(p, r_in) }, .mge)), "0")
  try(utils::capture.output(evalq({ p2 <- Plane(list(1, 1, 1), normal_vector = list(1, 1, 0)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ s2 <- Segment3D(list(3, 0, 0), list(4, -1, 1)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ distance(p2, s2) }, .mge)), "sqrt(2)/2")
  try(utils::capture.output(evalq({ h <- Symbol("h", positive = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ s_sym <- Segment3D(list(0, 0, h), list(1, 0, h)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ r_sym <- Ray3D(list(0, 0, h), list(1, 0, h)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ distance(p, s_sym) }, .mge)), "h")
  expect_identical(.mgs(evalq({ distance(p, r_sym) }, .mge)), "h")
})

