# test_util
.mge <- .mgs_env()
test_that("util: test_idiff matches SymPy", {
  try(utils::capture.output(evalq({ x <- Symbol("x", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ y <- Symbol("y", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ t <- Symbol("t", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ f <- Function("f") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ g <- Function("g") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ circ <- ((x^2) + (y^2)) - 4 }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ ans <- (((-3) * x) * (((x^2) / (y^2)) + 1)) / (y^3) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ ans }, .mge)), "-3*x*(x^2/y^2 + 1)/y^3")
  expect_identical(.mgs(evalq({ ans }, .mge)), "-3*x*(x^2/y^2 + 1)/y^3")
  expect_identical(.mgs(evalq({ idiff(circ, y, x, 3) }, .mge)), "-3*x*(x^2/y^2 + 1)/y^3")
  try(utils::capture.output(evalq({ explicit <- (12 * x) / (sqrt((-(x^2)) + 4)^5) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ equals(subs(ans, y, solve(circ, y)[[1]]), explicit) }, .mge)), "True")
  expect_identical(.mgs(evalq({ idiff((x + t) + y, list(y, t), x) }, .mge)), "-Derivative(t, x) - 1")
  expect_identical(.mgs(evalq({ idiff((f(x) * exp(f(x))) - (x * exp(x)), f(x), x) }, .mge)), "(x + 1)*exp(x)*exp(-f(x))/(f(x) + 1)")
  expect_identical(.mgs(evalq({ idiff(f(x) - (y * exp(x)), list(f(x), y), x) }, .mge)), "(y + Derivative(y, x))*exp(x)")
  expect_identical(.mgs(evalq({ idiff(f(x) - (y * exp(x)), list(y, f(x)), x) }, .mge)), "-y + exp(-x)*Derivative(f(x), x)")
  expect_identical(.mgs(evalq({ idiff(f(x) - g(x), list(f(x), g(x)), x) }, .mge)), "Derivative(g(x), x)")
  try(utils::capture.output(evalq({ fxy <- y - ((((-10) * (((-sin(x)) + (1 / x))^2)) + (tan(x)^2)) + (2 * cosh(x / 10))) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ idiff(fxy, y, x) }, .mge)), "-20*sin(x)*cos(x) + 2*tan(x)^3 + 2*tan(x) + sinh(x/10)/5 + 20*cos(x)/x - 20*sin(x)/x^2 + 20/x^3")
})

test_that("util: test_intersection matches SymPy", {
  expect_identical(.mgs(evalq({ intersection(Point(0, 0)) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ intersection(Point(0, 0), 3) }, .mge)), "ERR TypeError: \\nExpecting sequence of coordinates, not `int`")
  expect_identical(.mgs(evalq({ intersection(Segment(list(0, 0), list(2, 0)), Segment(list(-1, 0), list(1, 0)), Line(list(0, 0), list(0, 1)), pairwise = TRUE) }, .mge)), "[Point2D(0, 0), Segment2D(Point2D(0, 0), Point2D(1, 0))]")
  expect_identical(.mgs(evalq({ intersection(Line(list(0, 0), list(0, 1)), Segment(list(0, 0), list(2, 0)), Segment(list(-1, 0), list(1, 0)), pairwise = TRUE) }, .mge)), "[Point2D(0, 0), Segment2D(Point2D(0, 0), Point2D(1, 0))]")
  expect_identical(.mgs(evalq({ intersection(Line(list(0, 0), list(0, 1)), Segment(list(0, 0), list(2, 0)), Segment(list(-1, 0), list(1, 0)), Line(list(0, 0), slope = 1), pairwise = TRUE) }, .mge)), "[Point2D(0, 0), Segment2D(Point2D(0, 0), Point2D(1, 0))]")
  try(utils::capture.output(evalq({ R <- 4.0 }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ c <- intersection(Ray(Point2D(0.001, -1), Point2D(0.0008, -1.7)), Ellipse(center = Point2D(0, 0), hradius = R, vradius = 2.0), pairwise = TRUE)[[1]]$coords }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ R <- Float(4, 5) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ c2 <- intersection(Ray(Point2D(0.001, -1), Point2D(0.0008, -1.7)), Ellipse(center = Point2D(0, 0), hradius = R, vradius = 2.0), pairwise = TRUE)[[1]]$coords }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ c2 }, .mge)), "[0.00071429, -2.0000]")
})

