# test_curve
.mge <- .mgs_env()
test_that("curve: test_curve matches SymPy", {
  try(utils::capture.output(evalq({ x <- Symbol("x", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ s <- Symbol("s") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ z <- Symbol("z") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ c <- Curve(list(2 * s, s^2), list(z, 0, 2)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ c$parameter }, .mge)), "z")
  expect_identical(.mgs(evalq({ new_sym("Tuple", c$functions) }, .mge)), "(2*s, s^2)")
  expect_identical(.mgs(evalq({ arbitrary_point(c) }, .mge)), "Point2D(2*s, s^2)")
  expect_identical(.mgs(evalq({ arbitrary_point(c, z) }, .mge)), "Point2D(2*s, s^2)")
  try(utils::capture.output(evalq({ c <- Curve(list(2 * s, s^2), list(s, 0, 2)) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ c$parameter }, .mge)), "s")
  expect_identical(.mgs(evalq({ new_sym("Tuple", c$functions) }, .mge)), "(2*s, s^2)")
  try(utils::capture.output(evalq({ t <- Symbol("t") }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ arbitrary_point(c) != Point(2 * t, t^2) }, .mge)), "True")
  try(utils::capture.output(evalq({ t <- Symbol("t", real = TRUE) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ arbitrary_point(c) }, .mge)), "Point2D(2*t, t^2)")
  expect_identical(.mgs(evalq({ arbitrary_point(c, z) }, .mge)), "Point2D(2*z, z^2)")
  expect_identical(.mgs(evalq({ arbitrary_point(c, c$parameter) }, .mge)), "Point2D(2*s, s^2)")
  expect_identical(.mgs(evalq({ arbitrary_point(c, NULL) }, .mge)), "Point2D(2*s, s^2)")
  expect_identical(.mgs(evalq({ plot_interval(c) }, .mge)), "[t, 0, 2]")
  expect_identical(.mgs(evalq({ plot_interval(c, z) }, .mge)), "[z, 0, 2]")
  expect_identical(.mgs(evalq({ geo_rotate(Curve(list(x, x), list(x, 0, 1)), sym_pi / 2) }, .mge)), "Curve((-x, x), (x, 0, 1))")
  expect_identical(.mgs(evalq({ Curve(s, list(s, 1, 2)) }, .mge)), "ERR ValueError: Function argument should be (x(t), y(t)) but got s")
  expect_identical(.mgs(evalq({ Curve(list(x, x * 2), list(1, x)) }, .mge)), "ERR ValueError: Limit argument should be (t, tmin, tmax) but got (1, x)")
  expect_identical(.mgs(evalq({ arbitrary_point(Curve(list(s, s + t), list(s, 1, 2))) }, .mge)), "ERR ValueError: Symbol t already appears in object and cannot be used as a parameter.")
  expect_identical(.mgs(evalq({ arbitrary_point(Curve(list(s, s + t), list(t, 1, 2)), s) }, .mge)), "ERR ValueError: Symbol s already appears in object and cannot be used as a parameter.")
})

