  expect_identical(.mgs(evalq({ Parabola(Point(7, 8), Point(3, 8)) }, .mge)), "ERR ValueError: A 2nd Point or keyword \"slope\" must be used.")
  expect_identical(.mgs(evalq({ pa1$focus }, .mge)), "Point2D(0, 0)")
