  expect_identical(.mgs(evalq({ p_parameter(pa7) }, .mge)), "-1/2")
  expect_identical(.mgs(evalq({ vertex(pa7) }, .mge)), "Point2D(7/2, 7)")
  expect_identical(.mgs(evalq({ focal_length(pa4) }, .mge)), "1/2")
  expect_identical(.mgs(evalq({ p_parameter(pa4) }, .mge)), "1/2")
  expect_identical(.mgs(evalq({ vertex(pa4) }, .mge)), "Point2D(3, 13/2)")
  expect_identical(.mgs(evalq({ focal_length(pa8) }, .mge)), "1")
  expect_identical(.mgs(evalq({ p_parameter(pa8) }, .mge)), "1")
  expect_identical(.mgs(evalq({ vertex(pa8) }, .mge)), "Point2D(5, 0)")
