  expect_identical(.mgs(evalq({ aos }, .mge)), "Line2D(Point2D(7, 8), Point2D(5, 7))")
  expect_identical(.mgs(evalq({ pa12$directrix }, .mge)), "Line2D(Point2D(3, 7), Point2D(2, 9))")
  expect_identical(.mgs(evalq({ angle_between(pa12$directrix, aos) }, .mge)), "pi/2")
  expect_identical(.mgs(evalq({ eccentricity(pa12) }, .mge)), "1")
  expect_identical(.mgs(evalq({ equation(pa12, x, y) }, .mge)), "(x - 7)^2 + (y - 8)^2 - (-2*x - y + 13)^2/5")
  expect_identical(.mgs(evalq({ focal_length(pa12) }, .mge)), "9*sqrt(5)/10")
  expect_identical(.mgs(evalq({ pa12$focus }, .mge)), "Point2D(7, 8)")
  expect_identical(.mgs(evalq({ p_parameter(pa12) }, .mge)), "9*sqrt(5)/10")
  expect_identical(.mgs(evalq({ vertex(pa12) }, .mge)), "Point2D(26/5, 71/10)")
