  expect_identical(.mgs(evalq({ vertex(pa12r) }, .mge)), "Point2D(8/5, 53/10)")
})

test_that("parabola: test_parabola_intersection matches SymPy", {
  try(utils::capture.output(evalq({ l1 <- Line(Point(1, -2), Point(-1, -2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l2 <- Line(Point(1, 2), Point(-1, 2)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l3 <- Line(Point(1, 0), Point(-1, 0)) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p1 <- Point(0, 0) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p2 <- Point(0, -2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p3 <- Point(120, -12) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ parabola1 <- Parabola(p1, l1) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ intersection(parabola1, parabola1) }, .mge)), "[Parabola(Point2D(0, 0), Line2D(Point2D(1, -2), Point2D(-1, -2)))]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Parabola(p1, l2)) }, .mge)), "[Point2D(-2, 0), Point2D(2, 0)]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Parabola(p2, l3)) }, .mge)), "[Point2D(0, -1)]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Parabola(Point(16, 0), l1)) }, .mge)), "[Point2D(8, 15)]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Parabola(Point(0, 16), l1)) }, .mge)), "[Point2D(-6, 8), Point2D(6, 8)]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Parabola(p3, l3)) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ intersection(parabola1, p1) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Point2D(0, -1)) }, .mge)), "[Point2D(0, -1)]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Point2D(4, 3)) }, .mge)), "[Point2D(4, 3)]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Line(Point2D(-7, 3), Point(12, 3))) }, .mge)), "[Point2D(-4, 3), Point2D(4, 3)]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Line(Point(-4, -1), Point(4, -1))) }, .mge)), "[Point2D(0, -1)]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Line(Point(2, 0), Point(0, -2))) }, .mge)), "[Point2D(2, 0)]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Line(Point(0, 0, 0), Point(1, 1, 1))) }, .mge)), "ERR TypeError: Entity must be two dimensional, not three dimensional")
  expect_identical(.mgs(evalq({ intersection(parabola1, Segment2D(list(-4, -5), list(4, 3))) }, .mge)), "[Point2D(0, -1), Point2D(4, 3)]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Segment2D(list(0, -5), list(0, 6))) }, .mge)), "[Point2D(0, -1)]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Segment2D(list(-12, -65), list(14, -68))) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Ray2D(list(-4, -5), list(4, 3))) }, .mge)), "[Point2D(0, -1), Point2D(4, 3)]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Ray2D(list(0, 7), list(1, 14))) }, .mge)), "[Point2D(14 + 2*sqrt(57), 105 + 14*sqrt(57))]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Ray2D(list(0, 7), list(0, 14))) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Circle(p1, 2)) }, .mge)), "[Point2D(-2, 0), Point2D(2, 0)]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Circle(p2, 1)) }, .mge)), "[Point2D(0, -1)]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Ellipse(p2, 2, 1)) }, .mge)), "[Point2D(0, -1)]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Ellipse(Point(0, 19), 5, 7)) }, .mge)), "[]")
  expect_identical(.mgs(evalq({ intersection(parabola1, Ellipse(list(0, 3), 12, 4)) }, .mge)), "[Point2D(0, -1), Point2D(-4*sqrt(17)/3, 59/9), Point2D(4*sqrt(17)/3, 59/9)]")
})

