test_that("entity: test_subs matches SymPy", {
  try(utils::capture.output(evalq({ x <- Symbol("x", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ y <- Symbol("y", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p <- Point(x, 2) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ q <- Point(1, 1) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ r <- Point(3, 4) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ subs(Point(1, 2), Point(1, 2), Point(3, 4)) }, .mge)), "Point2D(3, 4)")
  expect_identical(.mgs(evalq({ subs(Circle(Point(0, 0), 5), Point(0, 0), Point(1, 1)) }, .mge)), "Circle(Point2D(1, 1), 5)")
  expect_identical(.mgs(evalq({ subs(Line(Point(0, 0), Point(1, 0)), Point(0, 0), Point(1, 1)) }, .mge)), "Line2D(Point2D(1, 1), Point2D(1, 0))")
  expect_identical(.mgs(evalq({ subs(Point3D(0, 0, 0), Point3D(0, 0, 0), Point3D(1, 1, 1)) }, .mge)), "Point3D(1, 1, 1)")
  expect_identical(.mgs(evalq({ subs(Plane(Point3D(0, 0, 0), list(0, 0, 1)), Point3D(0, 0, 0), Point3D(1, 1, 1)) }, .mge)), "Plane(Point3D(1, 1, 1), (0, 0, 1))")
  expect_identical(.mgs(evalq({ subs(Point(1, 2), list(1, 2), Point(3, 4)) }, .mge)), "Point2D(3, 4)")
  expect_identical(.mgs(evalq({ subs(Point(1, 2), Point(1, 2), Point(3, 4)) }, .mge)), "Point2D(3, 4)")
  expect_identical(.mgs(evalq({ subs(Point(1, 2), 1) }, .mge)), "ERR ValueError: \\nWhen a single argument is passed to subs it should be a dictionary of\\nold: new pairs or an iterable of (old, new) tuples.")
  expect_identical(.mgs(evalq({ subs(Point(1, 1), list(Point(1, 1), Point(1, 2)), 1, 2) }, .mge)), "ERR TypeError: Basic.subs() takes from 2 to 3 positional arguments but 4 were given")
})

test_that("entity: test_reflect_entity_overrides matches SymPy", {
  try(utils::capture.output(evalq({ x <- Symbol("x", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ y <- Symbol("y", real = TRUE) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ b <- Symbol("b") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ m <- Symbol("m") }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ l <- Line(list(0, b), slope = m) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ p <- Point(x, y) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ r <- geo_reflect(p, l) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ c <- Circle(list(x, y), 3) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ cr <- geo_reflect(c, l) }, .mge)), silent = TRUE)
  expect_identical(.mgs(evalq({ cr }, .mge)), "Circle(Point2D((m*(-b + y) - m*(b + m*x - y) + x)/(m^2 + 1), b + (b + m*x + m*(m*(-b + y) + x) - y)/(m^2 + 1)), -3)")
  expect_identical(.mgs(evalq({ area(c) }, .mge)), "9*pi")
  try(utils::capture.output(evalq({ pent <- RegularPolygon(list(1, 2), 1, 5) }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .untranslated <- TRUE }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .untranslated <- TRUE }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .untranslated <- TRUE }, .mge)), silent = TRUE)
  try(utils::capture.output(evalq({ .untranslated <- TRUE }, .mge)), silent = TRUE)
})

